window.CN_ZT = {"chapters": [{"id": "ck-c-zt2012", "title": "语文·2012山东春考真题卷", "kind": "pool", "desc": "2012年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下面语段中，加点字的注音完全正确的( ) 浓雾笼罩着河面，风声、涛声响成混①混．(hún)沌沌的一片，大颗大颗的雾②屑(xiāo) ． 冰末扑面而来。数十步开外的冰山雪堆间，几十米宽窄的一片洪流，像是一群：发怒狂 ③奔．(bèn)的金狮，抖动着黄色的④鬃(zōng)毛，推⑤搡(sǎng)挤撞成一团，⑥旋(xuán)卷 ． ． ． 腾跃而来，眨眼间又从三十多米高的断崖前轰然跌......", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "①②③", "B": "①③⑤", "C": "④⑤⑥", "D": "②④⑥"}}, {"q": "下列句子中，没有错别字的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "如果游人来到这里，就仿佛进人了神秘的仙境，顿时感到心旷神贻。", "B": "他传世的肖象，浓髯密髭，目光如矩，应属晚年的特写。", "C": "一群篷头垢面的年轻人，带者聒燥的活鸡活鸭，在缓慢而肮脏的火车上高谈阔论。", "D": "满载秋怨的小舟随琴声水远消逝了，诗人则踏着湿漉漉的诗行，忧郁地走进经典。"}}, {"q": "依次填人下列各句横线处的词语，恰当的( ) ①毋庸________，优秀的中华文化是人类历史上的一笔宝贵财富。 ②这位发言人________指出，日本政府必须正视钓鱼岛事件，以促进中日关系的和谐发 展。 ③________都江堰不坍，李冰的精魂________不会消散，李冰的儿子会代代繁術。", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "质疑庄重即使也", "B": "置疑郑重只要就", "C": "置疑庄重即使也", "D": "质疑郑重只要就"}}, {"q": "下列句子中标点符号的使用，正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "你是否由衷地从心里喜爱它(而不只是从脑海里)?", "B": "这起重大环境污染事件很快就在《新浪网》曝光了。", "C": "在阴晦的日子，看迷迷蒙蒙的远山，真能体味到“数峰凄苦，商略黄昏雨”的意境。", "D": "只有这枣子，柿子，葡萄，成熟到八、九分的七、八月之交，是北国的清秋的佳日。"}}, {"q": "下列句子中加点成语的使用，正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "有些独生子女常常对父母耳．提．面．命．，提出一-些过分的要求", "B": "游人登临黄山，常常被这大自然的巧．夺．天．工．所折服", "C": "大家看到他那滑稽的表情，想笑又不敢笑，纷纷侧．目．而．视．", "D": "苏轼的政论文章，清晰而有力，非常人可望．其．项．背．"}}, {"q": "下列句子中，没有语病的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "如果生命是树，那么理想是它的根，成功是它的果", "B": "写作文要有真情实感，切忌不要胡编乱造", "C": "本商场的当务之急是抓紧培养和提高新员工的服务水平", "D": "为提高公司产品的知名度，总经理决定在报纸、电台及各种传媒投放大量广告"}}, {"q": "填入下面横线处的句子，排序恰当的( ) 当车子驶进天台山，日光暖暖漏下，山风拂面，翠黛如洗，空气如水般纯澈，春光 柔顺似缎，侧耳倾听水与风的酬唱应答，________，________。________，________， 在碧绿的纯净中，阳光下只须借得几分云霭树荫，立即凉意爽然。 ①绕过盘山公路②还有竹林间跳跃的鸟语③映入眼帘的是-块躲在山中的璞玉④水与石 的耳鬓厮磨", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "②④③①", "B": "④②①③", "C": "④②③①", "D": "②④①③"}}, {"q": "根据语境，下列语言表达得体的( ) 某公司因多方面原因出现了暂时性经营困难，公司总经理打电话向几位合作伙伴寻 求帮助，他们给出了如下答复：", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "没问题，我们公司一定鼎力相助!", "B": "我们会提供必要的帮助，请你们好自为之。", "C": "别担心，我们一-定会尽力支持，帮助你们渡过难关。", "D": "资金问题恐难解决，经营策略方面可以给予指点，欢迎随时讨教。"}}, {"q": "从下面的材料中提炼三个关键词，恰当的( ) 2010 年7 月，欧洲食品安全委员会决定，任何含有6 种合成色素之一的食品，都必 须加上一条警告信息，说可能对儿童的注意力以及活动情况产生不良影响。与此相应的 是，美国一家消费者权益机构也曾在2008 年向美国食品药品监督管理局(FDA)提出：禁 止合成色素在食品中的使用，在最终禁用之前加上“可能有害”的警告信息。", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "食品合成色素警告信息", "B": "儿童可能有害警告信息", "C": "食品安全委员会合成色素不良影响", "D": "消费者权益机构合成色素可能有害"}}, {"q": "下列有关应用文知识的表述，不正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第10题；官方原卷未附答案", "opts": {"A": "写调查报告关键是要如实反映情况，所用材料要有点有面，避免以偏概全", "B": "感谢信、介绍信、贺信和证明信等专用书信的落款处必须加盖公章", "C": "便条是--种最简便的书信，它字数少，不用信封，在生活中使用频率很高", "D": "“XX 水利局2011 年工作总结”是全面总结的标题，“普法教育结硕果\"可以做专题总结 的标题"}}, {"q": "下列有关文学、文化常识的表述，正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "“林教头风雪山神庙”和“项庄舞剑，意在沛公”是我国古典小说中的精彩情节，鲍西亚 和玛蒂尔德是莎士比亚戏剧中的女性角色", "B": "《荷花淀》与《荷塘月色》是现代写景散文中的名篇，《致橡树》与《我愿意是急流》 是爱情诗歌中的佳作", "C": "纪传体史书以人物活动为中心记载历史，如《后汉书》;编年体史书按年代顺序记载历 史，如《左传》", "D": "称曾国藩为“文正”、称李白为“太白”是用其“字”来称呼，《老残游记》《饮冰室合集》 是以作者的“号”来为作品命名"}}, {"q": "下列选项中，不属于物联网技术推广应用的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第13题；官方原卷未附答案", "opts": {"A": "在家门外，用手机关闭屋内照明和电器", "B": ".上班途中，用手机实时查看家里的安防状况", "C": "在路上用手机发送照片和短信", "D": "驾车到小区门口就能打开地下车库的门"}}, {"q": "下列对物联网的描述，不正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "通俗地说，把日常生活中的许多电器设备等都加人到互联网中，就是物联网", "B": "物联网是-一个多技术发展环境", "C": "无线相容认证技术在物联网中扮演着重要角色", "D": "物联网最适合充当家庭中的主导网络"}}, {"q": "第三段中“这两种技术”是指(” )", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "无线相容认证技术与无线蜂窝技术", "B": "环境感知技术与无线通信技术", "C": "物体识别技术与环境感知技术", "D": "手机智能技术与无线蜂窝技术"}}, {"q": "作者提及文科学生四年大学生活的用意", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "为了让学生再回顾一下那些激动人心的日子", "B": "希望学生明白现实生活与大学生活是不一样的，而且差别很大", "C": "提醒学生今后要继续同古今中外的大师“会谈”", "D": "告诉学生走向社会后不要忘记在母校度过的宝贵时光"}}, {"q": "下列对文段中“安分守己”含义的理解，不正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "能够从容坦然地面对平凡的生活。.", "B": "当事业遭受挫折时，能正视现实，不自暴自弃。", "C": "顺应环境，随遇而安，放弃理想和追求。", "D": "不受世俗观念的影响，坚守内心的信念。"}}, {"q": "下列对文段中画线句子的理解，不正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "一个人是否幸福，与成功没有必然联系", "B": "成功的人可能幸福，也可能不幸福", "C": "在世俗眼光中不成功的人，也不一.定不幸福", "D": "成功的人不一-定幸福，但不成功的人肯定不幸福"}}, {"q": "对下列句中加点字的解释，不正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第21题；官方原卷未附答案", "opts": {"A": "居．则曰 居住", "B": "以俟．君子 等待", "C": "鼓瑟希． 同“稀”，稀疏", "D": "风．乎舞雩 吹风"}}, {"q": "下列句中，加点虚词的意义和用法相同的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第22题；官方原卷未附答案", "opts": {"A": "摄乎．大国之间浩浩乎．如冯虚御风", "B": "何．伤乎 何．至自沉溺缧绁之辱哉", "C": "千乘之．国 而绝秦赵之．欢", "D": "则．何以哉 于其身也，则．耻师焉"}}, {"q": "下列对孔子及其弟子的评价，不正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第23题；官方原卷未附答案", "opts": {"A": "孔子对学生循循善诱、和蔼可亲，体现了-一个教育家的风范。", "B": "子路胸怀大志，性情豪爽，但是有些鲁莽轻率。", "C": "冉有谦虚敦厚，谨小慎微，公西华除谦虚之外，还善于辞令，两人性格同中有异。", "D": "曾皙傲慢无礼，放浪形骸，没有高远的理想和追求。"}}, {"q": "下列对文段的分析，不正确的", "typ": "choice", "ans": "", "note": "2012年山东春季高考语文真题第24题；官方原卷未附答案", "opts": {"A": "以“言志”为线索，表达了孔子及其弟子各自的人生志向。", "B": "文段呈现的对话场景体现了和谐民主的师生关系。", "C": "通过简洁的对话、细腻的神情及动作描写来表现人物的性格志趣。", "D": "文段善用典故，内涵丰富;语言富丽华美，耐人寻味。 卷二(非选择题共90 分) 四、(本大题5 个小题，共20 分)"}}, {"q": "将第三题文言文阅读材料中画线的句子翻译成现代汉语。(3 分)", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "写出下列语段中空缺的名句。(任选五句)(5 分) (1)自古以来，许多文人墨客寄情于山水，并借助山水意象抒怀言志。李白发出 “①________，奔流到海不复回”的感慨，李煜诉说“问君能有几多愁，②________”的幽怨; 王维的“人闲桂花落，③________”展现了一种静美，苏轼的“横看成岭侧成峰， ④________”诠释了深刻的哲理。 (2)要成就一番事业，必须从小事做起，所谓“千里之行，①______”。与此同时，还要不 断学习和反思，因为“②________，则知明而行无过矣”。一路前行，不会永远是鲜花和 掌声，面对风雨，不妨大声吟诵“③________闲庭信步”。风雨过后，终会迎来属于自己 的一方晴空。", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "某校高三(2)班举行“我最喜爱的课文人物”评选活动。经过初选，确定蔺相如、水生 嫂、桑地亚哥为候选人，请从中选出一人，并仿照示例写出推选理由。(4分) 示例推选人物：张衡 推选理由;谦逊好学，成就科技的辉煌;从容淡静，不慕世俗的虚荣。张衡，以其卓 越的才能和高尚的人格贏得后人的敬仰。", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "有人说，现在是快餐文化时代，阅读经典已经过时了。针对上述观点，同学们展开了 辩论。作为反驳一方，写出你的观点并简要陈述理由。(4 分)", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "××公司要招聘-批推销员。下面是刘华写的一封自荐信，请找出在格式和内容上的四 处错误。(4 分) 自荐信 尊敬的××公司人力资源部领导： 您好! 我是××职业中专营销专业应届毕业生，现年18 岁。得知贵公司招聘推销 人员，特此应聘。在校期间，我学习成绩优秀，上小学时曾获得市绘画比赛三 等奖、区舞蹈比赛二等奖。寒暑假期间，我曾在××商场做过推销员，积累了一 定的工作经验。 我对贵公司仰慕已久，希望成为贵公司的一员。如果能被录用，我会加强 学习，勤奋工作，以优异的工作业绩回报公司对我的信任。 随信附上本人简历及各种证书复印件。 此致 敬礼 2014 年8 月20 日 五、(本大题6 个小题，共20 分) 阅读下面的文字，完成30~35 题。 父亲在世时，每逢过年我就会得到一盏灯。那灯是不．寻．常．的。 从门外的雪地上捡回一个罐头瓶，然后将一瓢滚热的开水倒进瓶里，啪的一声，瓶 底均匀地落下来，灯罩便诞生了。赶紧用废棉花将灯罩擦得亮亮的，亮到能看清瓶中央 飞旋的灰尘为止。灯的底座是圓形的，木制，有花纹，面积比灯罩要大上一圈，沿边缘 对称地钻两个眼，将铁丝从一只眼穿过去，然后沿着底座的直径爬行，再扎入另一只眼 中，铁丝在手的牵引下像眼镜蛇一样摇摆着身子朝上伸展，两个端头一旦汇合扭结在一 起，灯座便大功告成了。那时候从底座中心再钉透一根钉子，把半截红烛固定在钉子上。 待到夜幕降临时，轻轻捧起灯罩，嚓地点燃蜡烛，敛声屏气地落下灯罩，你提着这盏灯 就觉得无限风光了。 父亲给我做这盏灯总要花上很多工夫。就说做灯罩，他总要捡回五六个瓶才能做成 一个。不是把瓶子全炸碎了，就是瓶子安然无恙地保持原状，", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第29题；官方原卷未附答案"}, {"q": "结合文段，说说加点词语“不寻常”的含义。(2 分)", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第30题；官方原卷未附答案"}, {"q": "解释画线句子的含义，并指出其修辞方法。(4 分)", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第31题；官方原卷未附答案"}, {"q": "第八段中，作者写“红灯”和“冰灯”的作用是什么? (3 分)", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第32题；官方原卷未附答案"}, {"q": "父亲是一个怎样的人?在写父亲时，作者采用了哪些描写方法? (4 分)", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第33题；官方原卷未附答案"}, {"q": "结合文段内容，任选- -副对联进行补写，要符合对联的基本要求。(3分) (1)上联：___________下联：一篇短文道出儿女思念情 (2)上联：回想儿时年灯乐下联：___________________", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第34题；官方原卷未附答案"}, {"q": "一盏灯，给作者的童年带来无限欢乐，也给她留下美好的亲情回忆。在你的心灵深处， 是否也珍藏着一些这样的记忆?从中选取一个生活细节，简要写写你的体验和感悟。(4 分). 六、(本大题50 分)", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第35题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求作文。 历史的烟云，过往的岁月，总能引发人们无限的遐想。有人想穿越时空的隧道，回 到唐朝去聆听盛世之音;有人想逆着时光的快车，回到昨天去修改当初的决定;有人想回 到无忧无虑的童年，摆脱成长的烦恼;有人想回到曾经纯净的家园，远离工业文明带来的 污染...... 请以“回到_______”为题，写一篇文章。要求：将题目补充完整，立意自定，文体不限， 不少于700 字。", "typ": "write", "ans": "", "note": "2012年山东春季高考语文真题第36题；官方原卷未附答案"}]}, {"id": "ck-c-zt2013", "title": "语文·2013山东春考真题卷", "kind": "pool", "desc": "2013年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列加点字的读音，完全正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "同胞．(bāo) 混淆．(xiáo) 长堤．(dī) 玷．污(diàn)", "B": "承载．(zài) 横．财(héng) 模．样(mó) 纤．细(xiān)", "C": "埋．怨(mái) 兴．奋(xīng) 曲．折(qū) 笨拙．(zhuó)", "D": "给．予(gěi) 颈．项(jìng) 即．使．(jí) 筵．席(yán)"}}, {"q": "下列句子中，没有错别字的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "金庸的武侠小说风糜华语世界，征服了亿万读者。", "B": "这首诗歌脍灸人口，被多种版本的中学语文教材选用。", "C": "春天的西湖如一-幅淡淡的水墨画，吸引着中外游客纷至踏来。", "D": "近来，由于媒体的报道，人们对“数字地球”这一.概念产生了浓厚的兴趣。"}}, {"q": "依次填人下列各句横线处的词语，正确的是 ①星期天上午，我去找李明打篮球，________他走亲戚去了。 ②冬去春来，山上的冰雪________了，汇成- -条条小溪，从山上流下来。 ③这位音乐家最高兴的________获得了大奖，______在音乐中领悟到了人生的真谛。", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "恰好溶化不仅而且", "B": "恰好融化不是而是", "C": "恰巧融化不是而是", "D": "恰巧溶化不仅而且"}}, {"q": "下列句子中标点符号的使用，正确的是", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "多美呀!这万物复苏、生机盎然的春天。", "B": "“请弹一首欢快的曲子吧，”她说，“帮大家驱走忧伤。”", "C": "儿童的游戏，究竟是为了学习?为了娱乐?还是为了锻炼?", "D": "燕子去了，有再来的时候，杨柳枯了，有再青的时候，桃花谢了，有再开的时候。"}}, {"q": "下列句子中加点成语的使用，正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "这对失散多年的姐妹终于破．镜．重．圆．了。", "B": "虽然常年在恶劣的环境中从事科研工作，队员们却乐．此．不．疲．。", "C": "今年的国际风筝节如期开幕，世界各地的风筝爱好者趋．之．若．鹜．。", "D": "当代印刷业发达，出版的书刊寥．若．晨．星．.必须披沙拣金，才能觅得好书。"}}, {"q": "下列句子中，没有语病的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "她是我校的--位有30 多年教学经验的优秀的语文教师", "B": "由于同学们无私的帮助，使他感受到了集体的温暧", "C": "谁也不能否认徐志摩不是--位才华横溢的诗人", "D": "与会代表大都是各个单位的中坚和骨干"}}, {"q": "填人下面横线处的句子，排序正确的( ) 那夹江两岸连绵起伏的高山，有的耸峙云霄;有的横枕江面;有的像虎豹迎面扑来， 似巳躲闪不及;有的像天女腾空飞起，仿佛转瞬即逝。__________，__________， __________，__________，给江峡涂上神奇的色彩。 ①从高山的缺口伸出几道光束②如同仙人伸出发光的手臂③只偶然透过青蒙蒙的薄雾 ④太阳隐去", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "③②④①", "B": "④③①②", "C": "②①③④", "D": "④①②③"}}, {"q": "\"下列句子中，修辞的运用不同于其他三项的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "我们聆听智者的教诲，犹如花儿沐浴着阳光，小草吮吸着甘露", "B": "蝴蝶如同会飞的花朵，装点着美丽的春天", "C": "烟囱发出鸣鸣的声响，如在黑夜中哽咽", "D": "叶子出水很高，像亭亭的舞女的裙"}}, {"q": "在不影响原意的情况下，对下文必须删除的词语，判断正确的( ) 质量监督部门查获的假冒伪劣商品中，①又②再次发现假的“沙宣”洗发露。这些假洗发 露③完全④仿照中外合资广州宝洁有限公司⑤生产的⑥真正的“沙宣”深层滋润洗发露， 达到了⑦以假乱真的⑧仿真程度，让消费者真假难辨", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "①③⑥", "B": "②④⑧", "C": "②⑤⑦", "D": "①⑥⑧"}}, {"q": "下列有关应用文知识的表述，不正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第10题；官方原卷未附答案", "opts": {"A": "招领启事应写明拾到物品的具体数量和特征", "B": "事务性通知只把通知事项写清楚即可，不必发表议论", "C": "求职书的附件主要包括个人简历、证书复印件和发表作品复印件等", "D": "目标、步骤、措施是计划的三要素，其中“措施”解决“如何做好”的问题"}}, {"q": "下列有关文学、文化常识的表述，正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "重阳节有登高望远的习俗，端午节有踏青、禁火的习俗", "B": "欧.亨利和莫泊桑的代表作分别是《老人与海》和《项链》", "C": "鲁侍萍和窦娥同为生活在社会底层的有着悲惨命运的妇女形象", "D": "乡试的应试者为秀才，功名是举人;殿试的应试者为举人，功名是进士"}}, {"q": "根据文意，下列不属于双语者具有的优势的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第13题；官方原卷未附答案", "opts": {"A": "能够与更多的人交流", "B": "让人更聪明", "C": "提高语言认知能力", "D": "防止老年痴呆"}}, {"q": "对第四自然段“因祸得福”-词中“祸”“福”的理解，不正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "“祸”指双语者即使只使用一种语言，他的两种语言系统也都处于活跃状态", "B": "“祸”指双语者的- -种语言系统会干扰另一种语言系统", "C": "“福”指干扰会迫使大脑去解决内部冲突，从而得到增强认知能力的锻炼", "D": "“福”指使用双语的过程能够增强大脑的执行功能"}}, {"q": "下列不属于文段所使用的说明方法的是.", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "分类别", "B": "作比较", "C": "打比方", "D": "举例子"}}, {"q": "下列对文段主要内容的概括，恰当的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "作者喜欢孩子身上有几分书卷气。", "B": "作者阐述了读书的作用和方法。", "C": "读书大可随缘。", "D": "读书是认识自我并优化人生的重要手段。"}}, {"q": "结合小说《阿Q 正传》，对文段中王冶秋先生读书体会的解读，不正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "“笑得肚子痛”，是因为阿Q 的种种麻木不仁、自轻自贱、自欺欺人的言语举止和心理 活动，着实令人发笑。", "B": "“鄙弃其人”，是因为阿Q 身处被侮辱与被损害的地位而不觉醒，却用欺侮弱者的方式 来发泄自已被别人欺压的不平之气，令人鄙弃。", "C": "“同情上升为深思”，是因为阿Q 无辜却遭陷害的悲惨结局令人同情，而造成阿Q 不幸 命运的社会原因和文化背景令人深思。", "D": "阿Q“也许是报警器”。是因为阿Q 是个贼，现实生活中也有这样的人，我们应提高警 惕。"}}, {"q": "下列对文段中画线句子的理解，不正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "巴黎人非常傲慢，他们就连走路都是昂着头的", "B": "巴黎人具有高度的民族自信力，因为他们拥有卢浮宫这样的文化瑰宝", "C": "一个国家的文化遗产可以成为其人民的精神财富", "D": "作者以巴黎人为例，意在说明深厚的文化底蕴对人的精神面貌的影响"}}, {"q": "对下列句中加点词的解释，不正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第21题；官方原卷未附答案", "opts": {"A": "因．招樊哙出 趁机", "B": "故．遣将守关者 所以", "C": "而．听细说 却", "D": "樊哙覆其盾于．地 在"}}, {"q": "下列各组句子中，加点词的用法不同的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第22题；官方原卷未附答案", "opts": {"A": "头发上指人皆得以隶使之", "B": "毫毛不敢有所近大王必欲急臣", "C": "交戟之卫士欲止不内. 虽大风浪不能鸣也", "D": "先破秦入咸阳者王之假舟楫者，非能水也"}}, {"q": "下列句子与“客何为者”句式相同的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第23题；官方原卷未附答案", "opts": {"A": "不拘于时", "B": "而今安在哉", "C": "廉颇者，赵之良将也", "D": "举孝廉不行，连辟公府不就"}}, {"q": "下列对文段的理解，不正确的", "typ": "choice", "ans": "", "note": "2013年山东春季高考语文真题第24题；官方原卷未附答案", "opts": {"A": "樊哙撞倒守门卫士闯人军帐，怒视项羽，此时紧张气氛达到极点。", "B": "樊哙性格粗犷却很机智，是一员有勇有谋的武将。", "C": "项羽善于采纳意见，面对樊哙的斥责，非但不怒，反而虚心接受。", "D": "本段以精炼生动的语言刻画出人物鲜明的个性。 卷二(非选择题共90 分) 四、(本大题共5 个小题，共20 分)"}}, {"q": "将第三题文言文阅读材料中画线的句子翻译成现代汉语。(3 分) 夫秦王有虎狼之心，杀人如不能举，刑人如恐不胜，天下皆叛之。", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "写出下列横线处空缺的名句。(任选五句)(5 分) (1)__________________，，千金散尽还复来。 (2)别有幽愁暗恨生，_________________。 (3)举酒属客，_________________，歌窈宛之章。 (4)大汇东去，浪淘尽，_________________。 (5)那河畔的金柳，_________________。 (6)君子生非异也，_________________。 (7)_________________，，好之者不如乐之者。", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "从下列人物中任选-一个，参考画线处的两个句子，补写一句话，要符合作品情节或 人物的性格特点。(4分) 贝尔曼海伦●凯勒时传祥史铁生 在文学的殿堂里，众多作家和作品中的人物怀揣梦想，谱写出绚丽多彩的人生乐章。 司马迁的梦想是青史留芳，用生命抒写流传千古的绝唱;拉索尔的梦想是潜心写作，把成 长道路上的感悟与世人分享;_________________，________________。", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "在人才招聘会上，宋飞顺利通过了-家用人单位的初试。为了更好地应对三天后的面 试，他想向张老师请教几个问题。请从“请教”的角度为宋飞设计-段与老师交谈的开场白。 要求：语言流畅得体，不超过60 字。(4 分)", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "于超向同学孟石借--笔钱急用，以下是他写的借据，请指出其中的至少四处错误。(4 分) 借据 今借到孟石同学500 元整，一 星期后还清。 3 月9 日 五、(本大题共5 个小题，英20 分) 阅读下面的文字。完成30~35 题。 回家 海子少年时在这个城市的另一个区上中学，距家20 余里，公共汽车车票是8 分钱。 每个星期六，海子都要风雨不误地乘车赶回家。 那一天，海子的弟弟妹妹们，会早早地立在门口，等海子回来，好一起热热闹闹地 吃一顿比平常略微强一点的饭菜。 第二天，再跟海子哥到城外的小河套里去玩去疯。 有一回，爹对海子说：“海子....以.后不到过节或放长假，平常就不要回来了…… 爹说得挺犹豫。海子知道，爹每月工资76 元。海子还有两个哥哥，都很有出息， 在外地上大学。娘没有工作。 海子每个星期的来回路费，一角六分钱，对这个家庭很重要。 于是，海子连着两个星期没有回家。 又一个星期六，天已很晚，风刮得很大，海子突然回来了。娘和爹有些惊喜，又有 些生气。海子就气喘吁吁地说： “爹，娘，你们别不高兴，我没坐车，我是跑着回来的。” 爹．和．娘．一．时．无．语．。 过后，娘赶忙给海子做饭，热几个煎饼，再做一锅玉米面糊糊，想想，又狠狠心放 了好几滴荤油，很幸福地看海子唏哩呼噜地大口喝，喝得很香。 就这样，日子滑过很长的一段。 又有一回，娘思虑了许久，还是对海子说：“海子，这样下去还是不行啊。你看你 的鞋，过去半年一双，现在两个月就得一双……” 海子不语。 海子又是好几个星期没有回家。 海子再回家时，地冻天寒，娘老远看见，海子赤着双脚，一双鞋套在手上，裹一身 寒气跑回来。 娘．愣．住．", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第29题；官方原卷未附答案"}, {"q": "说说本文画线句子中省略号的含义。(2分)", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第30题；官方原卷未附答案"}, {"q": "各用一句话概括海子生前两次回家的经历。(4 分)", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第31题；官方原卷未附答案"}, {"q": "结合文章，简要分析加点的三个句子分别表现了爹娘怎样的心理。(3分)", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第32题；官方原卷未附答案"}, {"q": "本文在塑造人物方面主要运用了哪些描写手法? (3 分)", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第33题；官方原卷未附答案"}, {"q": "概括海子这一人物形象的特点。(4分)", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第34题；官方原卷未附答案"}, {"q": "家是成长的摇篮，家是憩息的驿站，家是避风的港湾...结合个人生活体验，简要写-- 写给你印象最深的一次回家的经历和感受。(4分) 六、(本大题50 分)", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第35题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求作文。 这些年，我们哭过，笑过，叛逆过; 这些年，我们爱过，恨过，感动过; 这些年，我们憧憬过，追求过，迷惘过; 这些年正渐行渐远， 那些事却永记心间。 请以“这些年，那些事”为题目，以中学时期亲身经历的事情为素材，用第-人称写一 篇不少于700 字的文章，文体自选(诗歌除外)，文中不得出现真实的姓名和校名。", "typ": "write", "ans": "", "note": "2013年山东春季高考语文真题第36题；官方原卷未附答案"}]}, {"id": "ck-c-zt2014", "title": "语文·2014山东春考真题卷", "kind": "pool", "desc": "2014年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点字的读音，完全相同的是", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "溺．爱亲昵．匿．名无法比拟．", "B": "汲．取觊．觎社稷．放荡不羁．", "C": "痊．愈鬈．曲顴．骨得鱼忘筌．", "D": "纨．绮挽．回蜿．蜒莞．尔一笑"}}, {"q": "下面语段中，加点词语没有错别字的( ) 记忆中，王老师总是以①独．出．新．裁．的方式，带领我们②翱．游．于知识的海洋;③闲．暇．时， 她时而与我们④谈．笑．风．声．，时而对我们语重心长。如今，我们虽已毕业多年，但王老师 的⑤谆．谆．教诲一直⑥铭．刻．在我们的心中。", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "①③④", "B": "③⑤⑥", "C": "②④⑥", "D": "①②⑤"}}, {"q": "依次填人下列各句横线处的词语，恰当的( ) ①__________昨天，微电影《无冀鸟》的点击量已经达到了10 万次。 ②阿根廷队凭借这个颇有__________的进球夺得了这届大赛的冠军。 ③__________只能作出一个这样的发现，__________已经是幸福的了。", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "截至争议即使也", "B": "截至异议既然就", "C": "截止争议既然就", "D": "截止异议即使也"}}, {"q": "下列句子中加点成语的使用，正确的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "2014 年世界杯足球赛即将举行，球员们个个摩．拳．擦．掌．，准备在绿茵场.上大显身手。", "B": "分别多年后，他们竞然在巴黎萍．水．相．逢．，彼此都格外激动。", "C": "某些同学总是对上课玩手机的做法不．以．为．然．，认为只要不打扰别人就行了。", "D": "这家企业经过改革创新，扭亏为盈，取得了急．功．近．利．的效果。"}}, {"q": "下列句子中，语意明确，没有语病的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "这次全国技能大赛，我一定说服老师和你--起去，这样你就不会特别紧张了。", "B": "中央电视台播出的《汉字听写大会》节目，激发了人们认汉字、写汉字的兴趣。", "C": "《时间都去哪儿了》这首歌一经推出，就在全国广泛引起了反响。", "D": "我终于想明白他为什么对我横眉冷对的原因了。"}}, {"q": "填入下列横线中的句子，恰当的( ) 不要以为“不能言而能不言”是多容易的事，“人之患在好为人师”，社会上鸡毛蒜皮 之事，____________，明明不大会说话，偏偏说个不停，自暴其短。", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "议论纷纷，说个不停，往往引爆口舌之战", "B": "议论纷纷，往往说个不停，引爆口舌之战", "C": "往往议论纷纷，引爆口舌之战，说个不停", "D": "往往引爆口舌之战，议论纷纷，说个不停"}}, {"q": "下列句子中，没有运用修辞手法的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "更多的时候，乌云四合，层峦叠嶂都成了水墨山水。", "B": "唯有风可以肆无忌惮游刃有余地穿过荆棘和竹篱笆。", "C": "我国当代文坛涌现出许多80 后作家，像韩寒、郭敬明等。", "D": "她依假在母亲的身边，诉说着，轻轻地诉说着，深情地诉说着....."}}, {"q": "下列对作家、作品的判断，正确的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "《最后一片叶子》的作者和《项链》的作者国籍相同。", "B": "《老人与海》的作者海明威和《红高粱》的作者莫言都获得过诺贝尔文学奖。", "C": "《致大海》相《面朝大海，春暖花开>都属于爱情诗。", "D": "《窦娥冤》和《威尼斯商人》都属于悲剧。"}}, {"q": "下列有关应用文知识的表述，不正确的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "条据是便条和单据的总称。单据也是-种便条，但适用范围仪限于钱、财、物方面。", "B": "启事既可以写在纸上张贴出去，也可以在报纸、电台、电视台、网络等媒体发布。", "C": "广告文案是广告作品中用以表达主题和创意的语言文字部分。", "D": "简报又称“动态”“简讯”“工作通讯”“内部参考”等，是一种公开发行的小报。"}}, {"q": "下列句子中加点的词语，不能体现说明文语言准确严密的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第13题；官方原卷未附答案", "opts": {"A": "其中波长为622~770 纳米的红色光在海面下不足百米处就被完．全．吸收。", "B": "继续向下，即使海水非常清澈，在水深不足600 米处，紫色光也彻．底．消失。", "C": "因此，全球的深海大．都．冰冷刺骨，水温只有0~1C。", "D": "没有了光照，深海也．就失去了太阳的热量供给。"}}, {"q": "'下列对第2 段中关于海水吸收可见光的说明，不正确的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "可见光的波长越长，照射进海里的距离越长。", "B": "随着海水深度的增加，可见光越来越少，直至消失。", "C": "深海海底，没有可见光。", "D": "在可见光中，紅色光最先被海水完全吸收，紫色光最后消失。"}}, {"q": "文章第2 段列举了一些反面事例进行论证，其目的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第16题；官方原卷未附答案", "opts": {"A": "充分证明不注重事实所造成的严重危害", "B": "说明中国古书上有很多不真实的记载", "C": "说明现今社会存在着很多奇怪的传说", "D": "充分证明注重事实对养成科学头脑有重要意义"}}, {"q": "关于本文的写作特点，不正确的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "结构规整紧凑，思路条理清晰", "B": "论证过程采用了递进式的结构", "C": "语言雅俗结合，语气自然亲切", "D": "运用了举例、引用等论证方法"}}, {"q": "对下列句中加点字的解释，不正确的", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "衡少善属．文 连缀，指写作", "B": "尝．问天下所疾恶者 曾经", "C": "公车特．征．拜郎中 特地征召", "D": "宦官惧其毁已，皆共目．之 眼睛"}}, {"q": "对下列句中加点字的解释，不正确的是", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第20题；官方原卷未附答案", "opts": {"A": "虽才高于．世 比", "B": "因以．讽谏 用", "C": "大将军邓骘奇其．才 他，代指张衡", "D": "十年乃．成 就"}}, {"q": "下列句子不是倒装句的是", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第21题；官方原卷未附答案", "opts": {"A": "安帝雅闻衡善术学", "B": "尤致思于天文阴阳历算", "C": "蚓无爪牙之利，筋骨之强", "D": "句读之不知，惑之不解"}}, {"q": "下列对文段的理解，正确的是", "typ": "choice", "ans": "", "note": "2014年山东春季高考语文真题第22题；官方原卷未附答案", "opts": {"A": "张衡虽经常游玩，但因其天资聪颖，所以仍能通五经，贯六艺。", "B": "张衡文学、政治才能极高，又深得皇帝赏识，所以仕途很顺利。.", "C": "张衡总是举止从容，淡泊宁静，不喜欢与俗人交往。", "D": "张衡痛恨宦官专权，与他们进行了坚决的斗争，最终遭到排挤。 卷二(非选择题共70 分) 四、(本大题共5 个小题，共15 分)"}}, {"q": "将第三题文言文阅读材料中画线的句子翻译成现代汉语。(2 分) 时天下承平日久，自王侯以下莫不逾侈。 __________________________________________。", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "写出下列横线处空缺的名句。(任选三句)(3 分) (1)盖文王拘而演《周易》，_____________________。 (2)_____________________，俟我于城隅。 (3)落红不是无情物，_____________________。 (4)舞榭歌台，风流总被，_____________________。 (5)_____________________，作为树的形象和你站在一起。", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "某校团委计划在六一国际儿童节这天，组织全校团干部去儿童福利院开展“爱心陪伴” 活动。请据此写一份通知，要求格式规范，内容简洁，有关内容可虚拟。(4分)", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "在语文课.上，老师正组织同学们就“如何看待文言文学习”的问题展开讨论。郑磊同 学认为，文言文远离现代生活，文字生涩难懂，缺乏现实意义，没有必要学习。课代表 则不这样认为。请站在课代表的立场，发表你的看法，不超过60 字。(3 分)", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "在微博、微信里，很多人用图片配上文字来表达自己的感情或看法。请从以下图片中 任选一幅，并为其配上文字。 要求符合图片传达的意思，不超过50 字。(3分) 五、(本大题共5 个小题，每小题3 分，共15 分) 阅读下面的文字，完成28~32 题。 聪明人和傻子和奴才① 鲁迅 奴才总不过是寻人诉苦。只要这样，也只能这样。有一日，他遇到一个聪明人。 “先生!”他悲哀地说，眼泪联成一线，就从眼角上直流下来。“你知道的。我所过的 简直不是人的生活。吃的是一天未必有一餐，这一餐又不过是高粱皮，连猪狗都不要吃 的，尚且只有一小碗……” “这实在令人同情。”聪明人也惨然说。 “可不是么!”他高兴了，“可是做工是昼夜无休息的;清旱担水晚烧饭，上午跑街夜磨 面，晴洗衣裳雨张伞，冬烧汽炉夏打扇。半夜要煨银耳，侍候主人耍钱;头钱②从来没分， 有时还挨皮鞭……” “唉唉……”聪明人叹息着，眼圈有些发红，似乎要下泪。 “先生!我这样是敷衍不下去的。我总得另外想法子。可是什么法子呢?……” “我想，你总会好起来……” “是么?但愿如此。可是我对先生诉了冤苦，又得你的同情和慰安，已经舒坦得不少 了。可见天理没有灭绝……” 但是，不几日，他又不平起来了，仍然寻人去诉苦。“先生!”他流着眼泪说，“你知 道的。我住的简直比猪窠还不如。主人并不将我当人;他对他的叭儿狗还要好到几万 倍……” “混账!”那人大叫起来，使他吃惊了。那人是一个傻子。“先生，我住的只是一间破 小屋，又湿，又阴，满是臭虫，睡下去就咬得真可以。秽气冲着鼻子，四面又没有一个 窗…… “你不会要你的主人开一个窗的么?” “这怎么行?……” “那么，你", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "仔细阅读文章，说说奴才主要从哪三个方面诉说了自己悲惨的生活处境。", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "文章用象征和对比的手法描写了奴才、聪明人和傻子三个截然不同的人物，表现了鲁 迅对当时中国社会和国民性的深刻认识。这三个人对待奴才的悲惨生活分别抱有怎样的 态度?用简要的语句加以概括。", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第29题；官方原卷未附答案"}, {"q": "文章以人物对话贯穿全篇，语言极富个性化。试从文中找出一例，并简要分析其表现 了人物怎样的心理和性格。", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第30题；官方原卷未附答案"}, {"q": "“他大有希望似的高兴地说”和“聪明人也代为高兴似的回答他”两句中的“似的”--词能 否去掉?为什么?", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第31题；官方原卷未附答案"}, {"q": "文章的结尾似乎解决了奴才的问题，奴才也高兴起来。你认为这是一个圆满的结局吗? 为什么? 六、(本大题40 分)", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第32题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求作文。 一件暖暖的毛衣，一句殷殷的教诲， 一路静静的陪伴，一段青涩的告白， 我知道，你爱我。是的，我知道。 谢谢你，让我永远不会独行。 请以“我知道你爱我”为题，写一篇不少于700 字的文章，文体自选(诗歌除外)，文 中不得出现真实的姓名和校名。", "typ": "write", "ans": "", "note": "2014年山东春季高考语文真题第33题；官方原卷未附答案"}]}, {"id": "ck-c-zt2015", "title": "语文·2015山东春考真题卷", "kind": "pool", "desc": "2015年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点字的注音，全部正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "迁徙．(xǐ) 脊．梁(jí)并行不悖．(bèi) 旌．旗蔽空(jīn)", "B": "窥．视(kuī) 裸露．(lòu) 相形见细(chū) 欲壑．难填(hè)", "C": "端倪．(ní) 俯瞰．(kàn) 强聒．不舍(guō) 惊鸿一瞥．(piē)", "D": "譬．如(bì) 喧嚣．( xiāo) 搔首踟．蹰(zhí) 怒不可遏．(è)"}}, {"q": "下列句子中，没有错别字的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "我汗流浃背，四肢颤抖，恨不得立刻躺倒在那片刚刚开垦的泥土之上。", "B": "科学家们称这种行踪鬼秘。忽隐忽现的岛屿为“幽灵岛”.", "C": "我们要做一个热爱生活的人，不能对周围的事物莫不关心。", "D": "教育界一些知名人士大声急呼：让好歌曲尽快走向我们的少年儿童."}}, {"q": "依次填人下列名句模线处的词语，恰当的是( ) ①走在林间，天色微暗，行人渐少，_______几声鸟鸣，为山林平添了几分寂静。 ②在我国很多地区，都有端午节挂荷包的习俗，据说这样可以_______疾病。 ③自闭症患者自我封闭。他们_______不会表达自已的感情，_______无法对他人的肢体 语言予以适当的回应。", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "偶尔祛除既又", "B": "偶然驱除既又", "C": "偶尔驱除因为所以", "D": "偶然祛除因为所以"}}, {"q": "下列句子中标点符号的使用，正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "啊!壹口高峡，你这黄河的奇迹，华夏大地的骄傲。", "B": "丝丝春雨——大约是今年的最后一场春雨了吧——在窗外静静地飘洒若。", "C": "营养学家指出，富含铁的食物很多，如猪肝、大豆、油菜、菠菜……等。", "D": "这里树木繁多、葱茏茂密，奇山异石、雄奇美丽、流泉飞瀑、蔚为壮观。"}}, {"q": "下列文段中加点成语的使用，不正确的是( ) 艺术的殿堂五彩缤纷，让我们目．不．暇．接．。这里有婀娜多姿的舞蹈，灵动飞扬的书法，也 有古朴典雅的雕塑，金．碧．辉．煌．的建筑，引．人．入．胜．的文学，栩．栩．如．生．的戏剧..艺术的领域 异常广阔，它的历程和人类历史一样漫长。", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "目不暇接", "B": "金碧辉煌", "C": "引人入胜", "D": "栩栩如生"}}, {"q": "下列句子中，语意明确。没有语病的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "2014 年这所中职学校招收的新生，是历年来最多的一年。", "B": "学校的模拟超市建好后，条码扫描器与同学们接触的机会就多了。", "C": "面对生态系统退化加速的严峻形势，我们必须大力推进生态文明建设。", "D": "秧歌是一种用锣鼓伴奏，主要流行于我国北方的广大农村。"}}, {"q": "依次填入下面横线处的句子，恰当的是( ) 小溪的步伐是艰辛的。然而，它从石板上滑下，__________；它从石崖上跌落， __________；它回旋在穴潭之中，__________。 ①便有了自己白练般的颜色 ②便有了自己不可推测的深沉. ③便有了自己铜的韵味的声音", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "③②①", "B": "③①②", "C": "②①③", "D": "①③②"}}, {"q": "下列有关文学、文化常识的表述，不正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "《鸿门宴X 报任安书)和(廉颇藺相如列传》都出自纪传体史书《史记》", "B": "《大学》中庸X 论语》孟子)并称为“四书”，是儒家的经典著作", "C": "古人说的“连中三元”中的“三元”指解元、会元和状元", "D": "自传体小说《成长)的作者拉索尔.贝克有“当代马克·吐温”之称"}}, {"q": "下列有关应用文知识的表述，不正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "简报的报尾应注明简报发放的范围和印发份数。", "B": "证明信要以机关、团体、企事业单位或个人的名义，凭借确凿的证据来出具.", "C": "事务性通知在结构上必须采用条款式，在内容上务必把通知事项写清楚。", "D": "计划的标题一般由单位、时限、内容和文种构成 。"}}, {"q": "下列选项，属于新闻背景材料的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "港督府的降旗仪式", "B": "查尔斯王子在雨中宜读英国女王赠育", "C": "五星红旗在添马舰营区升起", "D": "英国舰长爱德华·贝尔彻带领士兵占领港岛"}}, {"q": "下列对文段内容的分析，不正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第12题；官方原卷未附答案", "opts": {"A": "主要通过对英方告别仪式场景的描述，报道了香港回归这-令人难忘的历史事件", "B": "写港督乘坐带有皇家标记的“劳斯莱斯”车，是为了表现英方的尊贵与气派", "C": "“英国国旗”与“米字旗”两种说法体现出不同的感情色彩", "D": "英国对香港殖民统治的时间反复出现，表达了作者对这段沧桑历史的感叹"}}, {"q": "第一自然段中加点的“之”是指", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "致病的生物", "B": "大肠杆菌和酵母菌", "C": "减毒后的致病生物", "D": "病毒表面抗原基因"}}, {"q": "下列对疫苗的理解，不正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "疫苗就是淋巴素和免疫球蛋白，注射后可以消灭侵入机体的病菌和病毒", "B": "儿童注射麻疹减毒疫苗后，可获得对麻疹的自动性免疫", "C": "大肠杆菌和酵母菌在制造乙肝疫苗时起到了重要的作用", "D": "采用基因工程技术生产出的疫苗，不会给人类带来危险"}}, {"q": "对下列句子中加点词的解释，不正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "子路出而弃．之 丢弃", "B": "是欲死．我 使....死", "C": "取水还． 回来", "D": "乃怀．石盘 怀里"}}, {"q": "下列句子与“孔子尝游于山”句式相同的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "盖文王拘而演《周易》", "B": "加之以师旅", "C": "蚓无爪牙之利，筋骨之强", "D": "大王来何操"}}, {"q": "下列对文段的理解，不正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "“恚孔子”“欲中孔子”生动刻画了子路的粗鲁形象。", "B": "孔子的回答充分体现了他的智慧和机敏。", "C": "孔子明知有虎，却让子路去取水，说明他置学生的安危于不顾。", "D": "语言简洁传神，故事生动有趣，耐人寻昧。"}}, {"q": "下列对文中画线句子的理解，正确的是", "typ": "choice", "ans": "", "note": "2015年山东春季高考语文真题第20题；官方原卷未附答案", "opts": {"A": "子路在水所这个地方遇到老虎，与虎搏斗，打死老虎，割下虎尾，放人怀中。", "B": "子路在水所这个地方遇到老虎，与孔子共同打虎，制下虎尾，放入怀中。", "C": "子路在取水的地方遇到老虎，与虎搏斗，抓着虎尾把虎打死，制下虎尾，放入怀中。", "D": "子路在取水的地方遇到老虎，与虎搏斗，抓着虎尾把虎打死，将老虎放入怀中。 第II 卷(非选择题共70 分) 四.(本大题3 个小题，共10 分)"}}, {"q": "(3 分)写出下列横线处空缺的名句。(任选三句) (1)但我不能放歌，_________________。 (2)_________________，此时无声胜有声。 (3)寄蜉游于天地，_________________。 (4)人非圣贤，__________________? (5)__________________，清泉石上流。", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第21题；官方原卷未附答案"}, {"q": "(3 分)概括下面语段的主要内容，不超过35 个字(含标点符号)。 不同种类的斑马有着不同宽狭的条纹，这是同类相认的标记，其黑白相间的颜色也 是一种保护色。在阳光或者月光的照射下，黑白的色泽吸收和反射光线的作用不一样， 身躯的轮廓也就吏幻无定，而又能同森林草原的背景巧妙地协调起来。这样，猛兽就不 容易发现它们。", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第22题；官方原卷未附答案"}, {"q": "(4 分)李小虎中职毕业后，开了一家名为惠达的电器维修店。因所在小区拆迁改造， 店铺搬迁到了幸福路66 号。在新址开始营业的时间是2015 年5 月18 日。请代他拟一 份迁址启事。 要求：格式规范，内容明确，语句通顺。 五，(本大题5 个小题，每小题3 分，共15 分) 阅读下面的文字，完成24~28 题. “有钱是多么快活!”坐在茶几旁的肖夫人，当她拿起精致的银茶壶倒茶时，心里也许 是这样想的。 她身上的穿戴，屋里的陈设，无不显示出家财万贯的气派。她满西春风，得意之情 溢于言表。然而，由此而认定她是个轻浮的人，却是不公平的。 “你喜欢这幅画，我很高兴，”她对面前那位正襟危坐的年轻艺术家说，“我一直想 得到这幅名作，这是我丈夫上星期给我买的。” “美极了!\"年轻人赞许地说，“你真幸运。” 肖夫人笑了，那两条动人的柳眉扬了扬。她的双手细嫩而白皙，犹如用粉红色的蜡 铸成似的，把那只金光灿灿的戒指衬得更加耀人眼目。她举止娴静，既不抚发整衣，也 不摆弄小狗或者茶杯。她深深懂得，文雅能给予人一种感染力。 “幸远?”她说：“我并不相信这套东西。选择才是决定一切的。” 年轻人大概觉得，她将富有旧于选择两字，未免过于牵强。但他什么也没说，只是 很有分寸的点点头，让肖夫人继续说下去。 “我的情况就是个明证。” “你是自己选择当有钱人的哕?”年轻人多少带点揶揄的口吻。 “你也可以这样说。十五年前，我还是一个拙笨的学生... 肖夫人略为一停，故意给对方说点恭维话的机会。 “你看，”肖夫人继续说：“我那时只知道玩，身上又有一种叫什么自然美的东西， 但却有两个年轻人同时爱上了我。到现在我也搞不清楚他们", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "简要概括第一自然段的内容，并说说其在文中的作用。", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "小说运用了哪些人物描写的方法?", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "小说的结局有何特点?请列举-篇你所学过的具有类似特点的小说。", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "简要分析肖夫人这一人物形象的特点。", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "漫漫人生路，每个人都会面临- -些非常重要的选择，比如专业、职业.朋友、伴侣等。 简要谈谈小说中肖夫人的选择给你的启示。 六、(本大题45 分).", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求作文。 假如我能使一颗心免遭不幸 我将不会活着无意义 假如我能抚慰一个悲哀的生命 或令一个痛苦止息 或让一个昏厥的知更鸟. 重回巢里 我将不会活着无意义 (作者为美国诗人艾米莉·迪金森) 要求：①自选角度，自拟标题；②除诗歌外，文体不限；③不少于700 字；④文中不得 透露本人相关信息。", "typ": "write", "ans": "", "note": "2015年山东春季高考语文真题第29题；官方原卷未附答案"}]}, {"id": "ck-c-zt2016", "title": "语文·2016山东春考真题卷", "kind": "pool", "desc": "2016年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点的字，每对读音都相同的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "庇．护/裨．益 湍．急/惴．惴不安", "B": "主角．/号角． 自诩．/栩．栩如生", "C": "国粹．/憔悴． 沉湎．/冠冕．堂皇", "D": "沮．丧/诅．咒 屏．障/屏．气凝神"}}, {"q": "下列词语中，没有错别字的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "松驰亲和力口干舌燥", "B": "脉博孺子牛断章取义", "C": "斑驳播蓝曲甜言蜜语", "D": "气概度假村义不容词"}}, {"q": "依次填入下列各句横线处的词语，恰当的是( ) ①我们只要放慢脚步，静下心来，就会______到人生很多的苦与乐。 ②蒲松齡故居有一个______的小花园，因中几尊怪石，增添了“聊斋”的气氛。 ③人生正如攀爬高山，______跌落了100 次，______要安静地开始第101 次的攀爬。", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "体味精制如果那么", "B": "体验精制即使也", "C": "体验精致如果那么", "D": "体味精致即使也"}}, {"q": "下列句子中标点符号的使用，正确的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "“我不知道是谁的挂号信退回来了?”张师傅说。", "B": "我生平最受用的有两句话：一是“责任心”，二是“趣味”。", "C": "版画是在不同材料的版面上(如木板、石板、铜板等)通过手工制版印刷而成的。", "D": "中国的年俗：如剪窗花呀、贴春联呀、放鞭炮...每-项都有丰富的文化内涵。"}}, {"q": "下列句子中，语意明确，没有语病的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "目前，我国应对金融危机的抗危能力和调控措施正在不断提高。", "B": "青年教师所缺乏的，一是理论水平不高，二是实践经验不多。", "C": "研究表明，吃适量的水果、蔬菜和苦瓜有助于预防多种慢性病。", "D": "由于剧本的原因，演员巩俐曾多次婉拒好菜坞的邀约。"}}, {"q": "把下列句子组成语意连贯的语段，排序最恰当的是( ) ①再过一两个月，池水一结冰，连残荷也将消逝得无影无踪 ②连日来，天气突然变寒 ③那时荷花大概会在冰下冬眠，做着春天的梦 ④她们的梦一定能够圆的 ⑤池塘里荷叶虽然仍是绿油油一片，但是看来变成残荷之日也不会太远了", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "③⑤②①④", "B": "②⑤①③④", "C": "②①⑤④③", "D": "⑤③④②①"}}, {"q": "下列有关文学，文化常识的表述，错误的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "《拿来主义》的作者是现代文学家鲁迅，《我愿意是急流)的作者是俄国的普希金。", "B": "儒家思想的代表人物孔子和孟子并称“孔孟”，唐朝诗人李白和杜甫并称“李杜”。", "C": "“五经”指《诗》《书》《礼》《易》《春秋》，“五音”指宫、商、角、微，羽五个音阶。", "D": "古时对别人称自已亲属时，常在称号前加“家”或“舍”；称别人亲属时加“令”。"}}, {"q": "下列对课文内容的表述，正确的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "《林黛玉进贾府)描写了黛玉初进大观园，与王熙凤、贾宝玉.薛宝钗等人相见的情景。", "B": "《明湖居听书)刻画了王小玉的艺术形象，细腻传神地描摹了说唱艺术之美。", "C": "《列车上的偶然相遇)讲述了小男孩拉索尔在母亲教育下逐渐成长的故事。", "D": "《威尼斯商人》中的夏洛克不顾公爵的劝说，割掉了巴萨尼奥身上的一磅肉。"}}, {"q": "下列对人们“坚持补充营养索\"原因的表述，错误的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "人们一般能够承受营养素类药物的价格。", "B": "补充营养素是为健康来“保险\"。", "C": "长期服用可能使服用者产生的心理依赖。", "D": "医生建议所有人应该补充营养素类药物。"}}, {"q": "下列对文章的理解，正确的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第12题；官方原卷未附答案", "opts": {"A": "补充过量的维生素E 会影响骨骼健康。", "B": "营养素是人体所必需的，因此应大量服用。", "C": "日常饮食不一定能满足所有人必需的营养索。", "D": "半数的美国人和英国人都喜欢补充一些营养素。"}}, {"q": "下列对“最后一厘米”的理解，准确的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "遵循日本的标准和技术要求", "B": "精准求精.追求极致的工作态度", "C": "把产品当作自己的孩子，满怀爱，细心观察", "D": "是对自己劳动的肯定，对自己创造力的褒奖"}}, {"q": "下列说法，不符合文意的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "工匠精神是推动中国经济发展的原动力之一", "B": "庖丁的话说出了自已能够成功的根本原因", "C": "在中国古代思想谱系里，“文以载道”“技以载道”并重", "D": "我们不论做哪种工作，都需要发扬“敬事如仪”的精神"}}, {"q": "对下列句子中加点词的解释，错误的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "而绝．江河横渡", "B": "声非加疾．也 强，这里指声音洪大", "C": "君子生．非异也 生活", "D": "上．食埃土 向上，名词作状语"}}, {"q": "下列各组句子中加点词的意义和用法，完全相同的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "蚓无爪牙之．利 取之．无禁，用之不竭", "B": "蟹六跪而．二鳌 劳苦而．功高如此", "C": "善假于．物也 且立石于．其墓之门", "D": "无以．至千里 以．相如功大，拜为上卿"}}, {"q": "下列句子，与“假舆马者，非利足也”句式相同的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "将军战河北，臣战河南", "B": "屈原放逐，乃赋《离骚》", "C": "古之人不余欺也", "D": "非吾所谓传其道解其感者也"}}, {"q": "下列各句，没有论述学习方法或学习态度的是", "typ": "choice", "ans": "", "note": "2016年山东春季高考语文真题第20题；官方原卷未附答案", "opts": {"A": "吾尝终日而思矣，不如须臾之所学也", "B": "故不积鞋步，无以至千里；不积小流，无以成江海", "C": "锲而舍之，朽木不折；锲而不會，金石可镂。", "D": "蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也 第Ⅱ卷(非选择题共70 分) 四、(本大题3 个小题，共10 分)"}}, {"q": "写出下列横线处空缺的名句。(任选三甸)(3 分) (1)是故弟子不必不如师，_______________________。 (2)_______________________，直挂去帆济沧海。 (3)其声鸣鸥然，如怨如慕，_______________________，余音裊裊，不绝如缕。 (4)_______________________，只是近黄昏。 (5)如果我们选择了最能为人类而工作的职业，那么，_______________________，因为 这是为大家作出的牺牲。", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第21题；官方原卷未附答案"}, {"q": "把下面的长句改成4 个较短的句子，可以改变语序，增删字词，但不得改变原意。(3 分) 2016 年4 月8 日上午举行的一场由健力跑俱乐部组织的本市长跑爱好者参加的马拉 松比赛引起了媒体的关注。", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第22题；官方原卷未附答案"}, {"q": "根据以下内容，写一封介绍信。(4 分) 2016 年3 月18 日，海城职业中专学生刘芸到学校办公室对老师说：“老师好，我叫 刻芸，是2014 级商贸专业的学生。根据学校要求，我准备去鸿达外贸公司实习，请您 给我写一封介绍信。” 五、(本大题5 个小题，每小题3 分，共15 分) 阅读下面的文字，完成24~28 题。 绵绵土 牛汉 踏上塔克拉玛干大沙漠，我恍惚回到了失落了多年的一个梦境。几十年来，我从来 不会忘记，我是诞生在沙土上的。人们准不信，可这是千真万确的。我的第一首诗也是 献给没有见过的沙漠的。 此前，我真的踏上了沙漠，无边无沿的沙漠，仿佛天也是沙的。全身心澈荡着近乎 重逄的狂喜。 没有模仿谁，我情不自禁地五体投地，伏在热的沙漠上。我汗湿的前额和手心，沾 了一层细细的闪光的沙。 半个世纪以前，地处滹沱河①上游苦寒的故乡，孩子都诞生在铺着厚厚的绵绵土的 炕上，我们那里把极细柔的沙土叫作绵绵土。“绵绵”是我一生中觉得最温柔的一个词， 辞典里查不到，即使查到也不是我说的意思。孩子必须诞生在绵绵土上的习俗是怎么形 成的，祖祖辈辈的先人从没有想过。它是墨洁的领域，谁也不敢褻渎。它是一个无法解 释的活的神话。我的祖先们一定在想：人，不生在土里沙里，还能生在哪里?就像谷子 是从土里长出来一样的不可怀疑。 因此，我从母体落到人间的那一瞬间，首先接触到的是沙土，沙土在热炕.上焙得暖 乎乎的。我的润湿的小小的身躯因沾满金黄的沙土而闪着晶亮的光芒，就像成熟的谷稳 似的。接生我的仙园老姑姑那双大而灵巧的手用绵綿土把我抚摸得干干净净，还凑到鼻 子边闹了又闻，“只有土能洗掉血气。” 她常常说这句话", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "根据全文，概括作者笔下“绵绵土”的特点。", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "简要介绍作者家乡关于“绵绵土”的习俗。", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "文章第二段中加点的“伏\"能否换成“趴”?请说明理由。", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "从修辞方法的角度，分析文中画线句子的表达效果。", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "分析文章最后一段的作用。 六、(本大题45 分)", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求作文. . 我不应白白地耗費时间，去无尽地感慨生命的艰辛，也不应该自艾自怜命运怎么这 样不济，偏偏给了我这样一块不毛之地。我要做的是咬紧牙关，闷着脑袋，拼却全身的 力气，压到我的犁头上去。我决不企望有谁来代替，因为在这世界上，每人都有一块必 得由他自己来耕种的土地。 ——张洁 要求：①自选角度，自拟标题；②除诗歌外，文体不限；③不少于700 字；④文中 不得透露本人相关信息。", "typ": "write", "ans": "", "note": "2016年山东春季高考语文真题第29题；官方原卷未附答案"}]}, {"id": "ck-c-zt2017", "title": "语文·2017山东春考真题卷", "kind": "pool", "desc": "2017年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点字的注音，全部正确的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "扁．舟(biǎn) 狡黠．(xiá) 跌宕．起伏(dàng)", "B": "嗔．怒(chēn) 周匝(zā) 良莠．不齐(xiù)", "C": "恫．吓(dòng) 字帖．(tiě) 潸．然．泪下(shān)", "D": "哺．育(bǔ) 租赁．(lìn) 恪．尽职守(kè)"}}, {"q": "下列词语中，没有错别字的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "斑驳脏款称心如意", "B": "赔偿肤浅百舸争流", "C": "妆裱憧憬锲而不舍", "D": "领学真谛搬门弄斧"}}, {"q": "依次填入下列各句横线处的词语，恰当的是( ) ①数学公式也是一种世界语言，里面__________，着最严密的逻辑和自然辩证法。 ②林海千里，鸟雀争鸣，瀑布奔腾，看到这一切，我的心情久久难以__________。 ③他这种粗暴的做法，__________无助于问题的解决，__________会增加双方的矛盾。", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "贯串安静不但反而", "B": "贯穿安静不但而且", "C": "贯穿平静不但反而", "D": "贵串平静不但而且"}}, {"q": "下列句子中标点符号的使用，错误的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "“王师北定中原日，家祭无忘告乃翁。”是陆游爱国诗歌中的绝唱。", "B": "晴空万里，阳光灿烂，微风轻拂：真是一个难得的好天气。", "C": "近期，湖南卫视播出的电视剧《人民的名义》，赢得了观众良好的口碑。", "D": "怎样发挥思考的威力?要有强烈的志趣，要有明确的目标，要有科学的方法。"}}, {"q": "下列句子中加点成语的使用，错误的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "从图书馆回来，他发现课桌上的语文书不．胫．而．走．了.", "B": "王熙凤是一个精明强干、八．面．玲．珑．、逢场作戏的人。", "C": "这张画上的人物花鸟栩．栩．如．生．，吸引了众多参观者的目光。", "D": "春天的植物园百花齐放，风景优美，令人赏．心．悦．目．，流连忘返."}}, {"q": "下列句子中，没有语病的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "电子商务能否迅速发展，关键在于要造就一批专门技术人才。", "B": "昆曲是发源于苏州昆山的曲唱艺术，素有“百戏之母”的雅称。", "C": "参加青少年科技创新大赛的选手，大多是以中职学校的学生为主。", "D": "“绿色庄园”无公害蔬菜的生产量，基本上满足了当地百姓的生活。"}}, {"q": "把下列句子组成语意连贯的语段，排序最恰当的是( ) ①猜想它以前很早以前的主人②一排排鹅卵石，一级级石阶③门都关闭着，让你去猜想 它的蕴藏④漫步在苏州的小巷中是一种奇特的经验⑤一座座门庭", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "④②⑤③①", "B": "②⑤④③①", "C": "④⑤②①③", "D": "②⑤①③④"}}, {"q": "下列有关文字.文化常识的表述，正确的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "《诗经》是我国第-部诗歌总集，也是我国浪漫主义诗歌的源头。", "B": "《雷雨》《骆驼祥子》都是中国话剧史上的经典之作，作者分别是曹禺、老舍。", "C": "“再拜”指第二次拜，表示礼节隆重，旧时书信末尾常用“再拜”表示敬意.", "D": "“遂通五经，贯六艺”中“六艺”指礼、乐、射、御、书、数六种学问和技能。"}}, {"q": "对下列句子修辞手法的判断，正确的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "我凭舷眺望，江水滔滔，一泻千里，向东流去。(排比)", "B": "苍苍的榕树，以无限的爱心庇护着劳苦而淳朴的人们。(夸张)", "C": "落在路旁的一些红色的花瓣，向我透露若这个园子里的风光。(拟人)", "D": "我听到绿叶丛中紫罗兰的嗫嚅，芳草里铃兰的耳谮，流泉边迎春花的低笑。(对偶)"}}, {"q": "下列对“春节的灵魂”的理解，不准确的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "除旧布新，团贺喜庆。", "B": "对天地自然的敬畏和感恩。", "C": "对先祖的追忆和缅怀。", "D": "体现中国传统生活的优雅。"}}, {"q": "下列说法，符合文意的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第12题；官方原卷未附答案", "opts": {"A": "从古至今，春节不仅是一种民俗，更是一种政治行为。", "B": "斋戒迎春典礼、祭祀山林向石头焚香等都是国家最重要的政治生活。", "C": "春节时天子及民间的许多做法，体现了人与自然和谐相处的生存意识。", "D": "正月禁止砍伐树林，不可捕杀幼兽、掏取鸟蛋等禁忌，全被现代人遗忘了。"}}, {"q": "下列对记忆的表述，正确的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "海马以更多地分泌蛋白分子的方式来提高记忆力。", "B": "远期记忆可以通过不断地回忆进行巩固。", "C": "随着衰老进程的推进，人们的记忆会无法挽回地丧失。", "D": "人脑会把日常生活中经历的所有事件随机记忆下来。"}}, {"q": "下列关于睡眠对记忆影响的分析，错误的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "深睡有助于增强人们的记忆。", "B": "晚上做梦可能会影响到记忆。", "C": "长时间的睡眠有利于记忆。", "D": "短期记忆的下降可以通过睡眠修复。"}}, {"q": "下列对各段说明方法的判断，正确的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第16题；官方原卷未附答案", "opts": {"A": "第①段——下定义", "B": "第②段——打比方", "C": "第④段——分类别", "D": "第⑤段——举例子 阅读下面的文言文，完成17~20 题。 秦王斋五日后，乃设九宾礼于延，引起使者蔺相如。相如至，谓秦王日：“秦自缪 公以来二十余君，未尝有坚明约束者也。臣诚恐见欺于王而负赵，故令人持壁归，间至 赵矣。且秦强而赵弱，大王遣一介之使至越，越立奉壁来。今以秦之强而先割十五都予 赵，赵岂敢留壁而得罪于大王乎?臣知欺大王之罪当诛，臣请就汤镬，唯大王与群臣孰 计议之。” 秦王与群臣相视而嘻，左右或欲引相如去，秦王园日：“今杀相如，终不能得壁也， 而绝秦越之欢。不如因而厚遇之，使归赵。赵王岂以一壁之故欺秦邪?”卒廷见相如，毕 礼而归之。"}}, {"q": "对下列句子中加点词的理解，错误的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "引．赵使者蔺相如 延请", "B": "间．至赵臭 名词作状语，从小路", "C": "臣请就．汤镬 完成", "D": "唯大王与群臣孰．计议之 通“熟”，仔细"}}, {"q": "下列各组句子中加点词的意义和用法，完全相同的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "乃设九宾礼于．廷况吾 与子渔樵于．江渚之上", "B": "且．秦强而赵弱若属 皆且．为所虏", "C": "大王遣一介之．使至赵不 如因面厚遇之．", "D": "赵岂敢留璧而得罪于大王乎．以吾一日长乎．尔"}}, {"q": "下列句子，与“臣诚恐见欺于王而负赵”旬式相同的是", "typ": "choice", "ans": "", "note": "2017年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "人皆得以隶使之", "B": "至激于义理者不然", "C": "请以秦之咸阳为赵王寿", "D": "句读之不知"}}, {"q": "写出下列横线处空缺的名句。(任选三句)(3 分) (1)揉碎在浮藻间，_____________。 (2)千呼万呼始出来，_____________。 (3)_____________，唯倜傥非常之人称焉。 (4)_____________，不舍昼夜。 (5)叶子出水很高，_____________。", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第21题；官方原卷未附答案"}, {"q": "从下列词语中任选3 个，写一段话。要求语意完整，合乎情理，书写规范，不超过 50 个字(含标点)。(3 分) 青春出彩创新敬业成长", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第22题；官方原卷未附答案"}, {"q": "指出下面这则简报在格式上的4 处错误。(4 分) 教育工作简报 (2017 年4 月16 日) ××市教育局 第8 期(总第90 期) 打造匠心筑梦中国 ××××××××××××××××××××××××××××××××××××××××××××××× ×××××××× ××××××××××××××××××××××××××××××××××××××××××××××× ×××××××× ________________________________________________________ 发：各县教育局 报：××省教育厅 (本期共印60 份) ________________________________________________________ 阅读下面的文字，完成24~28 题。 刷子李 冯骥才 天津码头上的人，全是硬碰硬。手艺人靠的是手，手上就必得有绝活。有绝活的， 吃荤，亮堂，站在大街中央；没能耐的，吃素，发蔫，靠边采着。各行各业，全有几个 本领齐天的活神仙。刻砖刘、泥人张、凤筝魏，机器王、刷子李等等。天津人好把这种 人的姓，和他们拿手擅长的行当连在一起称呼。叫长了，名字反没人知道。只有这一个 绰号，在码头上响当当和当当响。 刷子李是河北大街一家营造厂的师傅。专干粉刷一行，别的不行。他要是给您刷好 一间屋子，屋里任嘛甭放，单坐着，就賽升天一般美。最叫人叫绝的是，他刷浆时必穿 一身黑，干完活，身上绝没有一个白点。别不信!他还给自己立下一个规矩，只要身上 有白点，自刷不要钱。倘若没这本事，他不早饿咸干儿了? 但这是传说，人信也不会全信。行外的没见过的不信，行内的生", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "阅读第一二自然段，说说“刷子李”称呼的由来。(2分) .", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "如何理解文中画线句子的含义? (3 分)", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "在写刷子李展现绝活之前，先写关于他的“传说”，分析这种写作手法及作用。(4分)", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "作为天津码头上的能人，刷子李身上有哪些职业品质? (2 分)", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "阅读最后一段，你从中受到哪些启示? (4 分) 三、写作题(45 分)", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求作文。 人的一生，会经历许多刻骨铭心的时刻：儿时生病，你依在母亲的怀里，感受亲情 的溫暖；遇到控折，你得到老师的鼓励，重扬希望的风帆；女排夺冠，你发出胜利的呐 喊，激发强国的宏.....那一刻，让我们懂得了感恩，向善，学会了反省、思考、获得了勇 气+力...那一刻，已成为永恒的生命记忆，激励我们不断向前。 请以“那一刻，却永恒”为题目，写一篇文章。 要求；①自选角度；②除诗歌外，文体不限；③不少于700 字；④文中不得透露本 人相关信息。", "typ": "write", "ans": "", "note": "2017年山东春季高考语文真题第29题；官方原卷未附答案"}]}, {"id": "ck-c-zt2018", "title": "语文·2018山东春考真题卷", "kind": "pool", "desc": "2018年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点字的读音，全都正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "羞赧．(nǎn)剖．析(pāo) 同仇敌忾．(kài)", "B": "紊．乱(wěn)炽．热(chì) 垂涎．三尺(xián)", "C": "畸．形(qí) 污渍．(zì) 瞠．目结舌(chēng)", "D": "箴．言(zhēn)亲．家(qìng) 针砭．时弊(biǎn)"}}, {"q": "下列各组词语中，没有错别字的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "别致绊脚石迫不急待", "B": "沧桑名信片拔地而起", "C": "暴躁水彩画集思广益", "D": "寒喧协奏曲彪炳史册"}}, {"q": "依次填入下列各句横线处的词语，最恰当的是 ①实现______蓝图，需要大家时刻准备付出更加艰苦的努力。 ②我们应认真查找管理上存在的问题，并把问题______在萌芽状态。 ③______离开多久，他对老宅______怀有深深的牵桂和担忧。", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "宏伟消除无论都", "B": "宏大消除即使也", "C": "宏伟解除即使也", "D": "宏大解除无论都"}}, {"q": "下列句子中标点符号的使用，正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "山谷一侧是整齐的小粮库、紧闭门户的小仓房；另一侧散落着五六家农舍。", "B": "苏州拙政园的“留听阁”，命名采用了“留得枯荷听雨声.”这句诗的意思。", "C": "夫妻俩正谈论着城里人喜欢什么口味的点心?哪家粮油店的面粉最便宜?", "D": "我握过各种各样的手一粗手、白手、嫩手，但是都没有留下什么印象。"}}, {"q": "下列句子中加点成语的使用，正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "除了几件旧衣服，他现在一．文．不．名．，为了糊口，必须出门挣钱", "B": "上次学业水平考试，多数同学的成绩比较理想，不合格者凤．毛．麟．角．", "C": "他演讲时联系现实生活，妙语连珠，巧．舌．如．簧．，给年轻人很多启发", "D": "河东的鞭炮响彻云霄，河西的鞭炮振．聋．发．聩．，两下争强斗胜，互不相让"}}, {"q": "下列句子中，没有语病的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "我国宏观经济年均增速约7.3%左右，对全球经济增长贡献率超过30%。", "B": "有人说，掌声是另一种语言，它既是情感的表达，也是情绪的反映。", "C": "由于生活的压力和高强度的工作，让不少年轻人经历着“成长的烦恼”。", "D": "这次活动之所以成功，原因是由于解决了“为了谁”“依靠谁”的问题。"}}, {"q": "依次填入下面横线上的语句，排序最恰当的是( ) 日头要落山时，采莲人背起竹篓，戴上斗笠，涉入浅浅的泥巴里，把已经成熟的蓬蓬一 朵朵摘下来，放在竹篓里。______，______，______，______，______。 ①得先挖出里面的莲子②采回来的蓬蓬③要用小刀一粒一粒剥开④蓬子外面有一层粗 壳⑤晶莹洁白的蓬子就会滚落一地", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "②①④③⑤", "B": "①①⑤②③", "C": "②③④①⑤", "D": "③②①④⑤"}}, {"q": "下列有关文化、文学常识的表述，正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "“豆蔻”“弱冠”“巾帼\"“面立”都是古人对年龄的称谓。", "B": "小说(阿Q 正传》窦娥冤》的题目中都含有主人公的名字。", "C": "《张衡传》是(汉书)中的一篇人物传记，作者是南朝人范晔。", "D": "“举酒欲饮无管弦”中“管”代指箫、笛之类的乐器演奏的音乐。"}}, {"q": "李湖到建筑公司面试时，他的自我介绍有以下内容，其中表达最恰当的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "我叫李湖，男，21 岁。籍贯，济南。从小到大，我读了13年的书。", "B": "大学时，我把业余时间都用在了健身上，我的外号是“运动达人”。", "C": "我学的是土木工程专业，节假日常到建筑工地实践，锻炼自已。", "D": "我自信稳重，聪明好学，一定会为你们公司做出很大贡献。"}}, {"q": "文中第二段的“这一点”是指", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "写文章有足够的书籍资料可供查阅", "B": "下笔写文章不用查书", "C": "不用查书就能把文章写得出类拔萃", "D": "拟圣旨时能引经据典"}}, {"q": "下列对文章的理解和分析，不正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第12题；官方原卷未附答案", "opts": {"A": "用苏东坡的故事，引出论题，同时使文章更有趣味。", "B": "徐特立关于学习的比喻，强调了读书的目的和意义。", "C": "作者认为读书不只为了写作，还能使人更新知识，提升能力。", "D": "喻证、例证、引证和对比论证的运用，增强了文章的说服力。"}}, {"q": "下列对“迷你\"制冷器的表述，不正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "是一种可转化电能或热能的柔性电热聚合物膜。", "B": "制冷效率高、成本低，对环境零污染。", "C": "突破了传统蒸汽压缩制冷装置体积大的局限。", "D": "小巧的特点为各种实际应用开辟了新途径。"}}, {"q": "下列句子中加点词的解释，不正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "正襟危．坐而问客日端坐", "B": "山川相缪．通“缭”，盘绕", "C": "下．江陵攻占", "D": "而卒莫消．长．也消失"}}, {"q": "下列各组句子中，加点词的意义和用法相同的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "侣鱼虾而．友麇鹿 去今之基而．葬焉", "B": "举匏樽以．相属 以．吾一日长乎尔", "C": "则．物与我皆无尽也于其身也，則．耻师焉", "D": "寄蜉蝣于．天地 又有若老人咳且笑于．山谷中者"}}, {"q": "下列对文段中商线旬子的翻译，正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "①这不是曹孟德围困周瑜的地方吗", "B": "②本来是一代的英雄啊，可是怎么在(战争中失败)呢", "C": "③流去的(水)像这样(不断地流去)，可是并没有流走", "D": "④这大自然无穷无尽的宝藏对我和你都很适合"}}, {"q": "下列对文段的理解和分析，不正确的是", "typ": "choice", "ans": "", "note": "2018年山东春季高考语文真题第20题；官方原卷未附答案", "opts": {"A": "客人的回答抒发了对曹操的仰嘉之情，表达了老当益壮的决心和意志。", "B": "苏子借水与月阐发万物和人生变与不变的哲理，表明他能辩证地看问题。", "C": "苏子对清风、明月的看法和态度，体现了他旷达乐观的性格特点。", "D": "文段多处运用对偶和比喻，句式长短错落，韵脚灵活多变. 卷二(非选择题共70 分) 四、(本大题3 个小题，共10 分)"}}, {"q": "写出下列横线处空缺的名句。(任选三句)(3 分) (1)故木受绳则直.金就砺则利，____________，则知明而行无过矣. (2)鷹击长空，鱼翔浅底，____________。 (3)知我者________________，不知我者，谓我何求。 (4)________________，惊涛拍岸，卷起千堆雪。 (5)工欲善其事，____________。", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第21题；官方原卷未附答案"}, {"q": "根据下面材料，写一封证明信。要求：格式规范，内容完整。(4 分) . 何正阳，男，2013 年9 月至2016 年7 月就读于江海职业中专机电工程专业。他现 在宏达公司工作，毕业证不慎丢失。因公司事务需要，他于2018 年4 月16 日回校开具 毕业证明。", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第22题；官方原卷未附答案"}, {"q": "把下面四句话改写成一个长单句。要求：可以增删个别词语，但不得改变原意。(3分) ①创客是一群自主创业的人。 ②创客陶醉于自己的奇思妙想。 ③创客充满澈情。 ④创客执著地要将每个“灵光一闪”变成现实。 创客是_______________________________。 五、(本大题5 个小题，共15 分) 阅读下面的文字，完成24~28题。 父亲还债 佛刘 我和父亲是在晚上到达县城的，刚一走出车站，父亲就说，你哥来接咱们了。我张 望了半天，也没看见哥哥。父亲指了指前面，我又仔细瞄．了．半．天．，才发现不远处冲我们 挥手的那个人就是哥哥。 哥哥很高兴，一边从父亲手里接过行李，一边对我笑了笑。我发现哥哥老了，其实 用“老”来形客显然是过分的，可是我那35 岁的哥哥真的老了。 哥哥的头发很乱，脸很黑，与我比起来，简直是两个世界的人。 父亲曾告诉我，农闲之余，哥哥会在火车站拉拉客人，挣点零花钱。 只陌生了一会儿，家就是原来熟悉的家了。我说，哥老了，刚才差一点认不出来了。 父亲不说话。 只是默默地抽着我给他买的烟。 其实，哥哥只比我大4 岁，从小就是我学习的榜样。他考第一名的时候，我还穿开 档裤乱跑呢；他当少先队大队长的时候，我才刚刚走进校园。但初中毕业时，哥哥漫发 挥好，没有考上县里的重点高中。父亲说，鸡窝里飞不出金凤凰，也别费那劲，种地得 了。哥哥痛苦了好几天，我看见他在夜里翻来覆去，长吁短叹。后来哥哥把他那些课本 放进一个大纸箱里，算是了结了过去的一段时光，而我就不同了，时隔几年，虽然我也 像哥哥一样没有考上县里的重点高中，但我坚持要上学，并警言和反对的父亲斗争到底。 两军相遇勇", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "分析第一段中加点词语的表达效果。”(2 分)", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "根据文中画线内容，概括哥哥具有的美德。(3 分)", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "如何理解“父亲还债”? (3分)", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "简要分析最后一段“我”的心理活动。(3 分)", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "没有亲情滋养，不会有“我\"现在的一切，请谈谈读完本文后的感受。(4 分) 六.(本大题45 分)", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求作文。 1998 年，洪家光从技校毕业，当了一名普通工人。他苦练专业技能，高标准要求自 己，成为了优秀车工。2008 年，他带领团队研发航空发动机叶片滚轮精密磨削技术。面 对高科技技水难关的挑战，他刻苦攻读，掌握了系统的理论知识。经过5 年的努力，1500 多次尝试，他们获得了成功。2018 年1 月，39 岁的洪家光获国家科技进步二等奖。现 在，他已是中国舷发黎明公司的首席技师。 要求：①自选角度；②自拟题目；③除诗歌外，文体不限；④不少于700 字；⑤文 中不得透露本人相关信息。", "typ": "write", "ans": "", "note": "2018年山东春季高考语文真题第29题；官方原卷未附答案"}]}, {"id": "ck-c-zt2019", "title": "语文·2019山东春考真题卷", "kind": "pool", "desc": "2019年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点字的读音，全都正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "猝．然(cù) 輩．声(fěi) 振聋发聩．(kuì)", "B": "泅．水(qiú) 半晌．(shǎng) 舐．犊情深(shì)", "C": "应．届(yīng) 挫．折(cuò) 有的．放矢(dí)", "D": "慰藉．(jí) 竹篙．(gāo) 殒．身不恤(yǔn)"}}, {"q": "下列各组词语中，没有错别字的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "呕歌提纲明辩是非语无伦次", "B": "凑和泯灭面面俱到莫明其妙", "C": "蛰伏诙谐层峦叠嶂侃侃而谈", "D": "喟然迷团奋发图强大相径廷"}}, {"q": "依次填人下列各句横线处的词语，最恰当的是( ) ①职校学生要实现美好的青春梦想，从一开始就得良好的意志品质。 ②做一个有______有品位的人，我们才能真正享受人生。 ③在实现民族伟大复兴的道路上，我们守候在静止的岸，做飞速行驶的舟。", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "塑造修养不但而且", "B": "锻造修养与其不如", "C": "锻造涵养不但而且", "D": "塑造涵养与其不如"}}, {"q": "下列句子中标点符号的使用，不正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "多么美呀，多么精巧啊，我们祖国的语言!", "B": "遇上亲友家中有喜丧事，母亲必亲自去贺吊一份礼也许只是两吊小钱。", "C": "清漪园(后来的颐和园就是在这个基础上建造起来的)是圆明园的许多属园之一。", "D": "我已经爱过、恨过、欢笑过......细细想来，便知晴日多于阴雨，收获多于劳作。"}}, {"q": "下列句子中加点成语的使用，正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "人们对教育的期待总是水．涨．船．高．，我们要始终坚持优先发展教育事业。", "B": "为学生搭建成长的舞台，是学校领导首．当．其．冲．的任务。", "C": "运用信息化手段进行教学，有些教师不知所措，有些教师却如．坐．春．风．。", "D": "火灾前的巴黎圣母院是一座美轮美奂、高．屋．建．瓴．的著名建筑。"}}, {"q": "下列句子中，没有语病的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "不但我们的作品要立足文化传统，而且还要关照文化现实。", "B": "新的时代是否具有互联网思维，能够帮助个人实现创造性发展。", "C": "经过这次全国大赛的锻炼，使我的技能有了很大程度的提升。", "D": "以“绿色生活.美丽家园”为主题的北京世园会吸引了八方游客。"}}, {"q": "把下列句子组成语义连贯的语段，排序最恰当的是( ) ①撩逗起人生悲欢离合的回忆和对明天深远的情思 ②但它是痴迷于秋天的歌手 ③听不懂诗人们的咏叹 ④蝈蝈虽然不知人间事 ⑤蝈蝈在秋风起秋叶落时对着夕阳吟唱", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "④②⑤③①", "B": "①③②⑤①", "C": "⑤②④③①", "D": "⑤①④②③"}}, {"q": "下列有关文学、文化常识的表述，不正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "曲牌都有一定的曲调、唱法、字数，句法等，如“端正好”“叨叨令”。", "B": "老舍，现代作家，代表作有长篇小说《骆驼祥子》《四世同堂》等。", "C": "古代把一夜分为“五更”，“一更”大致相当于晚上23 时至次日凌晨1 时。", "D": "农历的每月初一叫“朔”，十五叫“望”，最后一天叫“晦”。"}}, {"q": "下列句子中，没有使用修辞手法的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "我像其他的父母一样，虽然极端同情你却不能不批评你。", "B": "苍苍的榕树默默地张开温柔的翅膀，带给他们夏8 的阴凉。", "C": "地也，你不分好歹何为地!天也，你错勘贤愚枉做天!", "D": "住宅的寒伧，墙壁的黯淡，家具的破旧，衣料的粗陋，都使她苦恼。"}}, {"q": "下列选项中，没有对书法艺术产生影响的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "道家天人合一，阴阳辩证思想", "B": "儒家温良恭俭让的道德规范", "C": "东汉末年的一批书法理论专著", "D": "中国画强调线条勾勒和书写性"}}, {"q": "下列对本文内容的概括，不正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第12题；官方原卷未附答案", "opts": {"A": "从书法角度来观照中国文化，是比较便捷的方式", "B": "书法艺术最能代表民族物质，又有广泛群众基础", "C": "实用文字和书法艺术，二者的发展方向完全相反", "D": "中国人审美修养都源于最普適最实用的书法艺术"}}, {"q": "下列对本文内容的理解，不正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "视觉AI 技术是人工智能走向大众的唯一发展方向。", "B": "视觉AI 能够让机器看懂、理解这个世界.", "C": "视觉AI 识别能力的迅猛发展源自于深度学习的突破。", "D": "未来更多的应用场景都将贴上视觉AI 的标签。"}}, {"q": "下列不属于视觉AI 研究内容的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "用摄影机和电脑代替人眼对图像进行特征提取。", "B": "对提取的图像特征进行有效分析.", "C": "训练模型对新的图像数据进行检测.识别。", "D": "建立图像或者多模态数据库并获取信息。"}}, {"q": "下列句子中加点词的解释，不正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "恨．私心有所不尽 遗憾", "B": "乃赋．(离骚》 创作", "C": "大底圣贤发．愤．之所为作也 决心努力", "D": "思垂．空文以自见 流传"}}, {"q": "下列句子中“者”字的意义和用法不同于其他三项的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "至激于义理者不然", "B": "且勇者不必死节", "C": "幽于粪土之中而不辞者", "D": "而陋者乃以斧斤考击而求之"}}, {"q": "下列句子中，与“而文采不表于后世也”句式相同的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "乃有所不得已也", "B": "而耻学于师", "C": "余犹记周公之被逮", "D": "石之铿然有声者"}}, {"q": "下列对文段的理解和分析，不正确的是", "typ": "choice", "ans": "", "note": "2019年山东春季高考语文真题第20题；官方原卷未附答案", "opts": {"A": "古代圣贤都是因“有所郁结”而著书，以“述往事，思来者”。", "B": "司马迁选择受辱不死的原因是为了使“文采”“表于后世”。", "C": "文段辞气雄浑，柔中见刚，情怀慷慨，激切感人，至情至真。", "D": "司马迁将个人价值置于历史长河中来衡量，超脱了“死节”观念的束缚。 卷二(非选择题共70 分) 四、(本大题3 个小题，共10 分)"}}, {"q": "写出下列横线处空缺的名句。(限选三旬)(3 分) (1)想当年：金戈铁马，_______________。 (2)_______________，波心荡，冷月无声。 (3)闻道有先后，_______________如是而已。 (4)子日：“_________________，见不贤面内自省也。” (5)没有拿来的，人不能自成为新人，没有拿来的，_______________。", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第21题；官方原卷未附答案"}, {"q": "根据下面材料，写一张请假条。要求：格式规范，内容明确，语言简洁通顺。(3 分) 2019 年4 月25 日，学生马凌江跑操时不慎把脚扭伤，到医务室诊治，医生建议休 养3 天，他需要给班主任老师写张请假条。", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第22题；官方原卷未附答案"}, {"q": "在横线上补写句子。要求：句式基本相同，内容相关，使用嗅觉、听觉两种感觉。(4 分) 初夏的齐鲁大地，一丛丛绚烂的野花开遍原野，_______________ ， _________________，一丝丝清凉的微凤抚过心房，令人陶醉，令人向往。 五、(本大题5 个小题，共15 分) 阅读下面的文字，完成24~28 题。 活着的手艺 王往 他是一个木匠。是木匠里的天才。 他会对着一棵树说，这棵树能打一个衣柜，一个桌子。面子多大，腿多高。他都说 了尺寸。过了一年，树的主人真的要用这棵树了，说要打一个衣柜，一张桌子。他就站 起来说，那是我去年说的，今年这棵树打了衣柜桌于，还够打两把椅子。结果，和他说 的分毫不差。 他锯木头，从来不用弹线，木工必用的墨斗，他没有。他加的榫子，不用油漆，你 也看不出痕迹。他雕的坳蝶、鲤鱼，让那要出嫁的女孩看得目不转睛，真害怕那蝴蝶飞 了，那鲤鱼游走了。他的雕刻能将木料上的职疵变为点睛之笔。一道裂纹让他修饰为鲤 鱼划出的水波或是蝴蝶的触须，一个节疤让他修饰为蝴蝶翅膀上的斑纹或是鲤鱼的眼睛。 树死了，水匠又让它以另一种形式活了。 做家具的人家，以请到他为荣。主人看着他背着工具走过来，就会对木料说：“他 来了，他来了!” 是的，他来了，死去的树木就活了。 我在老家的时候，最爱看他做木工活儿。他快速起落的斧子砍掉那些无用的枝权， 直击那厚实堅厚的树皮；他的锯子自由而不屈地穿梭，本屑纷落；他的刻刀细致而委婉 地游移..他给爱好写作的我以启示：我的语言要像他的斧子，越过浮华和滞涩，直击那“木 头”的要害；我要细致而完美地再现我想象的艺术境...多年努力，我未臻此境。", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "如何理解第五段中“他来了，死去的树木就活了”的含义? (2分)", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "“但是，木匠在我们村里的人缘并不好”一段在全文中的作用是什么? (2分)", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "两处画线句子反映出“木匠”什么样的心理? (4 分)", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "文章运用了哪些人物描写方法塑造“木匠”这-形象? (3分)", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "结合文章内容与专业成长，谈谈你对“职业要有职业的尊严”这句话的认识。(4 分) 六、(本大题45 分)", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求完成作文. 这是一个信息化的时代，互联网深刻影响着我们的生活；这是一个创新的时代，新 理念、新成果、新现象、新词汇体现了社会的巨变；这是一个开放包容的时代，“一带 一路”搭建了中国与诸多国家互惠共贏的平台；这是一个多元多彩的时代，有梦想就能 找到适合自已的发展空间…… 请以“生活在_________的时代”为题目，写一篇文章。 要求：①将题目补充完整；②自选角度；③除诗歌外，文化不限；④不少于700 字； ⑤文中不得透露本人相关信息。", "typ": "write", "ans": "", "note": "2019年山东春季高考语文真题第29题；官方原卷未附答案"}]}, {"id": "ck-c-zt2020", "title": "语文·2020山东春考真题卷", "kind": "pool", "desc": "2020年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点字的读音，全都正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "拂．晓(fó) 缠绕茎．(jīng) 胜券．在握(juàn)", "B": "脸颊．(já) 超负荷．(hé) 首当其冲．(chōng)", "C": "打烊．(yàng) 紧箍．咒(gū) 咎．由自取(jiù)", "D": "愜．意(qiè) 肥皂泡．(pāo) 坚贞．不屈(zhēng)"}}, {"q": "下列句子中，没有错别字的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "她整日刷洗杯盘碗牒，在盆沿上和锅底上磨粗了粉嫩的手指。", "B": "这些不同的意见可能会互相矛盾，让我们莫忠一是，不知所从。", "C": "悟透了这首诗精髓的人，又有哪位会妄想永葆荣华而贪得无厌呢?", "D": "牧草服贴地随大地起伏，尽管已是严冬，仍可想见盛夏时青绿的底色。"}}, {"q": "依次填人下列各句横线处的词语，最恰当的是( ). ①两个老同学十几年不通消息，彼此间_______起来。 ②“采菊东篱下，悠然见南山”，这“悠然”二字，真是_______得很。 ③_______我们的科学技术赶上了世界先进水平，_______还要学习人家的长处。", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "隔阂高雅倘若那么", "B": "隔膜闲雅即使也", "C": "隔膜高雅即使也", "D": "隔阂闲雅倘若那么"}}, {"q": "下列句子中，标点符号使用正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "他侧着头，仰视着上前方，似乎在追踪一个遥远的目标... ...", "B": "山谷内古木参天、流水潺潺、鸟语花香、环境十分清幽。", "C": "画中爱因斯坦的脸被画成小提琴，琴弦上曼舞着著名的物理学公式，E=me2。", "D": "后来他继续探索，将油画与水墨画的技法结合起来，又画了“黄河落日图”。"}}, {"q": "下列句子中，加点成语使用正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "这款商品的热销，为实现全年的销量目标起到了推．波．助．澜．的作用。", "B": "经过旷．日．持．久．的训练，他终于成为了运动场上最耀眼的明星。", "C": "干部要以．身．作．则．，注意自己的言行举止，为群众做好榜样。", "D": "公司严禁私自外出，个别员工还是义．无．反．顾．，我行我素。"}}, {"q": "下列句子中，没有语病的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "上个月，我们参观学习了这所学校开展疫情防控的先进经验。", "B": "手机行业的价格战日益惨烈，某品牌的价格甚至下降了一倍。", "C": "观看了纪录片《泰山挑山工》，对我们青少年启发教育很大。", "D": "这件事后，谁又能否认他是--位既有爱心又有才华的老师?"}}, {"q": "对下列语句的排序，最恰当的是( ) ①你抬眼看去 ②目光穿过街心 ③落在一墙的绚烂或者一窗的青葱上 ④再一眼便越过了对岸的庭院 ⑤望得到河里的水、水上的波 ⑥这才发现春天从未走远", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "①②⑤④③⑥", "B": "②⑥①⑤④③", "C": "①⑤④③②⑥", "D": "②⑤①③⑥④"}}, {"q": "下列有关文学、文化常识的表述，不正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "《稼轩长短句》是以作者的号来命名的，《七录斋集》是以作者的书斋名来命名的。", "B": "殿试是科举制最高级别的考试，由皇帝或其委派大臣主持，考生是会试录取的贡士。", "C": "古代尊称对方的母亲为令堂，谦称自己的弟弟为舍弟。", "D": "华阴由于地处华山北面而得名，汉阳则因位于汉水南面而得名。"}}, {"q": "下列场景中的语言表达，最恰当的是( ).", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "李教授到某公司参观，接待人员说：“您好!欢迎您来我们公司指导工作。您的到来， 让我们深感荣幸。”", "B": "小宋到服装厂找王经理联系业务，接待人员说：“对不起!你怎么没有预约?王经理正忙 着呢。你过段时间再来吧。”", "C": "一游客向小魏问路，小魏答：“往前走，过两个红绿灯，再拐个弯，过一个路口，不 用走多远就到了。”", "D": "病床上的老马询问自己的病情，朋友答：“你放心，该吃吃，该喝喝，家里的事儿就 交给我了!”"}}, {"q": "第一段中加点的“这个倾向”，在文中是指", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "中华文明的演进史灿若星河，镶嵌着许多文化瑰宝。", "B": "个体的文化创造要经历生命挤压碰撞等痛切体验。", "C": "杜甫等人的创作是源于其身世家世的兴衰颓败。", "D": "文明成果的产生需要创造者付出惨痛的生命代价。"}}, {"q": "下列对文章内容的概括分析，符合文意的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第12题；官方原卷未附答案", "opts": {"A": "我们常常为拥有众多文化瑰宝的五千年历史所感动。", "B": "有了可以赖以负重的基石底座，才可能生长出优质的文化果实。", "C": "乱象搅扰会导致这个时代无法对民族文化做出贡献。", "D": "因为文化建设不是虚幻的，所以文化楼体倒塌的破坏性更久远。"}}, {"q": "\"下列对文章中“疫苗”的表述，不正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "牛痘疫苗是人们为了消灭天花这种传染病而研发的。", "B": "疫苗通过保护易感人群来阻断传染病的传播。", "C": "疫苗可以帮助人的机体实现对某种疾病的主动免疫。", "D": "不同种类的疫苗在原理、效果等方面大同小异。"}}, {"q": "下列对文章内容的理解，正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "只有将传染病传播的三大要素都控制住，才可以阻断传染病的传播。", "B": "人的皮肤、黏膜可以确保人体不被细菌.病毒侵入。", "C": "新冠病毒属于RNA 病毒，所以疫苗对新冠病毒没有效果。", "D": "即使成功消灭了人群间的新冠病毒，新冠病毒仍会在自然界存在。"}}, {"q": "下列句子中加点词的解释，不正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "其后秦伐赵，拔．石城 攻下", "B": "廉颇送至境，与王诀．曰 告别", "C": "相如顾．召赵御史书曰 回头", "D": "赵亦盛．设兵以待秦 隆重"}}, {"q": "下列句子中“为”字的意义和用法与例句相同的是( ) 例句：秦王为．赵王击缶", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "圣人之所以为．圣", "B": "为．之声义", "C": "为．国以礼", "D": "若属皆且为．所虏"}}, {"q": "下列对文中画线句子的翻译，恰当的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "秦王派使臣告诉赵王，打算讨好赵王，相会在西河外渑池。", "B": "在这时蔺相如向前献上瓦缶，趁势跪下请求秦王击缶。", "C": "秦王身边的侍从要用刀杀相如，相如瞪着眼晴怒视他们，他们都散开了。", "D": "秦王直到喝尽了酒，始终未能占到赵国上风。"}}, {"q": "下列对文段的理解和分析，不正确的是", "typ": "choice", "ans": "", "note": "2020年山东春季高考语文真题第20题；官方原卷未附答案", "opts": {"A": "渑池会前廉颇送别赵王时，请立太子为王的一番话，表现了他耿耿忠心和过人胆识。", "B": "渑池会上蔺相如与秦王的斗争，突显他有勇有谋、蔑视强权、置生死于度外的特点。", "C": "司马迁善于描写矛盾冲突，文段集中展现秦赵两国的冲突和廉蔺二人之间的矛盾。", "D": "“跪请秦王”“张目叱之”等细节描写生动传神，使人物形象丰满逼真、跃然纸上。 卷二(非选择题共70分) 四、(本大题3 个小题，共10 分)"}}, {"q": "写出下列横线处空缺的名句。(限选三句)(3 分) 人生如白驹过隙，沿途的旖旎风光却让我们流连忘返。或许，有“烹羊宰牛且为乐， ①_________”的二三老友，江南烟雨塞外沙，仗剑走天涯；或许，有“静女其妹， ②_________的红颜知已，“③_________；我们共享雾霭、流岚、虹霓”。即便平平淡淡， 也希望“我有一所房子，面朝大海，④_________”。又或许，被生活千磨万击，可又有 什么关系!“竹杖芒鞋轻胜马，谁怕?⑤_________”，也未尝不可。至少，思想过，努力过， 奋斗.....", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第21题；官方原卷未附答案"}, {"q": "根据上联，将所给的短语连缀成下联。(3分) 短语：童叟无欺要论公德货真价实买卖 上联：物美品优，妇孺皆知，经营全凭诚信 下联：_________、_________、_________", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第22题；官方原卷未附答案"}, {"q": "指出下面通知在格式和内容上的4 处错误。(4 分) 关于举办“尔雅杯”礼仪知识大赛的通知 各班团支部： 为了丰富学生课余文化生活，提升学生礼仪素养，促进 文明校园建设，我校团委定于5 月23 日下午4：00 举办“尔 雅杯”礼仪知识大赛。请各班团支部组织本班选手按时参加 比赛。 此致 敬礼 2019 年5 月20 日 ①________________________________________ ②________________________________________ ③________________________________________ ④________________________________________ 五、(本大题5 个小题，共15 分) 阅读下面的文字，完成24~28 题。 家是生命中一盏橘黄的灯 王明亚 生命，是一个从荒芜到芳草萋萋的过程。在这个过程里，我们最不能忽略也无法忽 略的，是家。 第一次，用一个婴儿的姿态蹒珊着走出家门，扑闪着一双好奇的大眼睛，愣愣地不 知往哪里去。然后学着辨别家的方向一或许是一爿半启的门．扉．，或许是廊前摇摆的衣架， 或许是熟悉的猫．的．声．音．，或许是苦楝树下狗．的．饭．盆．，或许是一张永远等候在门口的笑． 脸．……点一滴，开始了一个人一生里对家的最深长的认识和依恋。 记得，上学后每天背着书包走在长长短短的田埂上的情景。有时是一个人，有时会 有一个伙伴；有时风雨交加，有时斜阳万丈。不管是每一天的清晨，还是每一天的黄昏， 总是那相似的没有改变的路。很多次想停步，因为疲惫，因为厌倦。 然后，一声近处的狗", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "如何理解文中开篇所说的“生命是一个从荒芜到芳草萋萋的过程”?(2 分)", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "第二段中，哪些词语生动刻画了“婴儿的姿态”?加点词语在文中代表什么?(3 分)", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "文中画线句子表现了怎样的家庭气氛? (3 分)", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "漂泊在外的日子里，文中的“我\"在感情上有怎样的变化? (3分)", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "文章的结尾说，家是“生命中一束橘黄的灯光”，而有家“生命才会熠熠生辉”。结合全 文谈谈你对此的理解。(4分) 六、(本大题45 分)", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求完成作文。 亲情在左，师恩在右，少年虽轻狂，过往岁月静好；理想在前，重任在肩，青春亦 无悔，前程色彩缤纷。回眸过去，五味杂陈；憧憬未来，山高路远。过去已去须珍惜， 未来已来要珍重。 请以“回眸·憧憬”为题目写一篇作文。 要求：①文体不限；②不少于700 字；③文中不得透露本人相关信息。", "typ": "write", "ans": "", "note": "2020年山东春季高考语文真题第29题；官方原卷未附答案"}]}, {"id": "ck-c-zt2021", "title": "语文·2021山东春考真题卷", "kind": "pool", "desc": "2021年山东省普通高校招生春季考试语文整卷（文字版原卷）：选择题、阅读、文言文、写作齐全；官方原卷未附参考答案，答案缺失已如实标注。", "n": 0, "target": 10, "pool": [{"q": "下列词语中加点字的读音，全都正确的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第1题；官方原卷未附答案", "opts": {"A": "束缚．(fú) 刹．那(chà) 为虎作伥．(chāng)", "B": "掺．杂(chān)潜．台词(qián)提纲挈．领(qiè)", "C": "侮．蔑(wǔ) 挨．日子(ái) 模棱．两可(lèng)", "D": "百舸．(kē) 订．书机(dìng) 百折不挠．(náo)"}}, {"q": "下列句子中，没有错别字的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第2题；官方原卷未附答案", "opts": {"A": "他痴迷绘画艺术，经过长期锤练，他的绘画能力有了很大提高。", "B": "电视剧《跨过鸭绿江》以振撼人心的故事给观众留下了深刻印象。", "C": "当代青年要实学实干，矢志追求更有高度.更有境界、更有品位的人生。", "D": "每个人都应树立理性的消费观念，励行节约，坚持绿色低碳的生活方式。"}}, {"q": "依次填人下列各句横线处的词语，最恰当的是( ) ①“十三五”以来，我国脱贫攻坚取得的巨大成就，使广大人民群众_______不已。 ②国际奥委会专家代表团来到北京，对冬奥会场馆建设情况进行实地_______。 ③消滴之水终可以磨损大石，_______由于力量强大，_______由于昼夜不舍的滴坠。", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第3题；官方原卷未附答案", "opts": {"A": "感愤考察不是就是", "B": "感奋考察不是而是", "C": "感奋考查不是就是", "D": "感愤考查不是而是"}}, {"q": "下列句子中，标点符号使用正确的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第4题；官方原卷未附答案", "opts": {"A": "今天，一场以“奋斗的青春最美丽”为主题的报告会在学校礼堂隆重举行", "B": "如何制订计划，如何保证实施，如何验证效果?都是我们要面对的重要问题", "C": "老师推荐阅读：《奥秘》探索》《博览》，这些书可以帮助我们提升科学素养", "D": "李清照，南宋著名的女词人，号易安居士，齐州章丘人(今山东章丘西北)"}}, {"q": "下列句子中加点成语的使用，不正确的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第5题；官方原卷未附答案", "opts": {"A": "经过兄弟俩多年的惨．淡．经．营．，这家小店终于红火起来", "B": "在多个部门的共同努力下，医院各项规章制度日．臻 ．完．善．", "C": "小王的毕业论文虽然不能达到最终要求，但也算差．强．人．意．", "D": "他十分注重自己的形象，每天出门前都打扮得道．貌．岸．然．"}}, {"q": "下列句子中，语意明确，没有语病的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第6题；官方原卷未附答案", "opts": {"A": "他背着爸爸和妈妈做了两项社会调查，得到了宝贵的资料", "B": "今年清明节，我院全体师生徒步来到烈士陵园举行了献花", "C": "同学们早早来到学校大门口，焦急地等待着凯旋的体育健儿", "D": "本着方便群众为原则，相关部门简化了营业执照的申办流程"}}, {"q": "对下列语句的排序，最恰当的是( ) ①很多选择都不是非此即彼②就没必要举棋不定③只管做决定，行动起来就好④“选择” 遍及生活的角角落落⑤如果感觉每一个选项都有道理", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第7题；官方原卷未附答案", "opts": {"A": "④①⑤②③", "B": "⑤③①②④", "C": "④⑤③②①", "D": "⑤②④③①"}}, {"q": "下列有关文学、文化常识的表述，正确的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第8题；官方原卷未附答案", "opts": {"A": "荀子是战国后期道家学派代表人物；倡导古文运动的韩愈，列“唐宋八大家”之首。", "B": "《老人与海》是美国作家海明威的小说，《故都的秋》是现代作家郁达夫的散文。", "C": "古时称女子二十岁为“及笄之年”，明清时期的“翰林”多为编修国史的文职官员。", "D": "“孝廉”指孝顺父母、敬爱兄长的人；“斋戒”指祭祀前洁身清心，以示虔诚。"}}, {"q": "冯铭收到一.张给父亲的请帖，如果他要将其中的内容以打电话的方式转告给出差的父 亲，下列说法最恰当的是( ) 请帖 尊敬的冯熙远先生： 欣逢家慈八十大寿，定于公历五月九日(星期日) 十二时，在嘉园饭店为家慈贺寿。 谨备寿宴，恭候光临。 王轩诚邀 二〇二一年五月六日", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第9题；官方原卷未附答案", "opts": {"A": "爸，五月九日到嘉园饭店吃饭，十二点呀，你可别忘了", "B": "爸，王轩伯伯让你于公历五月九日十二时到嘉园饭店为家慈贺寿", "C": "爸，王轩邀请你五月九日十二点到嘉园饭店参加他妈妈八十岁生日宴会", "D": "爸，王轩伯伯请你参加王奶奶的八十岁生日宴，这个星期天十二点，在嘉园饭店"}}, {"q": "下列对传统艺术“正成为年轻人喜爱的新时尚”原因的表述，不正确的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第11题；官方原卷未附答案", "opts": {"A": "传统艺术包含着源远流长的民族精神密码，并以高度审美化的方式呈现。", "B": "传统艺术创作在坚守艺术本体的前提下，符合了当代审美趋势与价值观。", "C": "传统艺术在传播上利用多种新媒体平台，切合当下年轻人的受教育程度。", "D": "传统艺术的名家、名角发挥自身的影响力，广泛参与形式多元的活动。"}}, {"q": "下列对文章内容的理解和分析，符合文意的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第12题；官方原卷未附答案", "opts": {"A": "将昆曲和梨园戏的历史作对比，突出传统戏曲的深厚文化底蕴。", "B": "京剧《曹操与杨修》被拍成3D 电影，是为了全面塑造曹操形象。", "C": "方锦龙、王珮瑜等名家参加多种电视节目，推动了传统艺术“破圈”。", "D": "为了证明新媒体平台强大的传播优势，知名艺术家直播“云练功”。"}}, {"q": "下列关于文中“光子”的说法，不符合文意的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第14题；官方原卷未附答案", "opts": {"A": "中性原子的产生使光子得以“脱耦”，摆脱离子的束缚传到远处。", "B": "早期光子波长不断被拉长变到微波波段，形成“微波背景辐射”。", "C": "随着宇宙的膨胀和冷却，“脱耦”后的光子平均温度-直在降低。", "D": "低温微波背景辐射光子和星系周围的高温热电子之间发生能量交换。"}}, {"q": "下列对文章内容的理解，符合文意的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第15题；官方原卷未附答案", "opts": {"A": "由于受地球温室效应影响，星系团周围的高温区域不断升温。", "B": "宇宙在一-次大爆炸后诞生，随后持续膨胀。这已得到科学验证。", "C": "气体不断被吸引聚积到“空洞”的过程中，温度会不断下降。", "D": "现有观测数据和研究结果尚不足以验证宇宙大尺度结构理论。"}}, {"q": "下列句子中加点词的解释，不正确的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第17题；官方原卷未附答案", "opts": {"A": "蹈死不顾，亦曷．故哉通“何”，什么", "B": "非．常．之谋难于猝发很，十分", "C": "视．五人之死比较", "D": "人皆得以隶．使之像对待奴仆那样"}}, {"q": "下列各组句子中加点词的意义和用法，完全相同的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第18题；官方原卷未附答案", "opts": {"A": "待圣人之出而．投缳道路吾尝终日而思矣", "B": "佯狂不知所之．者羡长江之无穷", "C": "列其姓名于．大堤之上虽才高于．世", "D": "哀斯墓之徒有其石也．而为之记师道之不传也．久矣"}}, {"q": "下列句子中，与“斯固百世之遇也”句式相同的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第19题；官方原卷未附答案", "opts": {"A": "和氏璧，天下所共传宝也", "B": "句读之不知，惑之不解", "C": "屈原放逐，乃赋《离骚》", "D": "将军战河北，臣战河南"}}, {"q": "\"下列对文段的理解和分析，不正确的是", "typ": "choice", "ans": "", "note": "2021年山东春季高考语文真题第20题；官方原卷未附答案", "opts": {"A": "通过对比“大阉之乱”时“缙绅”与“五人”的不同表现，突出五人激昂大义的气节。", "B": "“亦以明死生之大，匹夫之有重于社稷也”，既是对五人功绩的赞誉，也是对后人的激 励。", "C": "“不可谓非五人之力也”以双重否定的句式，有力肯定了五人在反阉党斗争中的作用。", "D": "文段部分以叙述为主，叙中有议，议中含情，使得文章事、理、情交融，感染力强。 卷二(非选择题共70 分) 四、(本大题3 个小题，共10 分)"}}, {"q": "写出下列横线处空缺的名句。(限选三句)(3 分) 许多诗人喜欢借古抒怀。李白在《行路难》中借南朝名将宗悫的典故，以 “①__________，直挂云帆济沧海”表明心迹；杜牧在《泊秦淮》中慨叹“②__________， 隔江犹唱《后庭花》”影射当时社会；苏轼在《念奴娇。赤壁怀古》中用“遥想公瑾当年， 小乔初嫁了，③__________，”对比自己的人生；辛弃疾在《永遇乐.京口北固亭怀古》 中借“廉颇老矣，④__________”抒发报国无门、壮志难酬的愤懑；毛泽东在《水调歌 头·游泳》中吟咏的“子在川上曰：⑤________”饱含时不我待的紧迫感。", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第21题；官方原卷未附答案"}, {"q": "用一句话概括下面语段的主要内容。要求：语言通顺，不超过20 字。(3 分) 纵观近年来的消费市场，国产品牌表现亮眼。新品牌崛起，国内的原创设计产品有 了越来越多的粉丝；老字号走红，大白兔奶糖、雅霜雪花膏、回力运动鞋等陪伴了几代 中国人的老品牌也在创新中焕发出. 新的活力。《2020 中国消费品牌发展报告》显示，过去一年，中国消费者购物车里 装着的，八成以上是国产品牌；另有数据显示，去年的“双11”，销售额过亿元品牌中， 国产品牌占比近六成。", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第22题；官方原卷未附答案"}, {"q": "2021 年4 月16 日，李大勇花50 万元人民币向张小鲁买了一套房子，他已向对方支 付42 万元。双方约定余款于当年八月底付清。请以李大勇的身份给张小鲁写张欠条。 要求：内容明确，格式规范，语言简洁通顺。(4 分) 五、(本大题5 个小题，共15 分) 阅读下面的文字，完成24~28 题。 追月人 张炜 爸爸回来得太突然了，出乎所有人的预料，所以大家都高兴坏了，都惊住了。妈妈 和外祖母过了三四分钟才醒过神，齐声问：“你怎么回来了?”爸爸语气十分平静地回答： “回家过节。”我亲眼看到妈妈脸上流下了两道泪水。外祖母没说什么，转身到黑影里忙 着什么。我心里一阵难过：我们如果早一点知道爸爸赶回来多好，可怜的爸爸，没有和 我们一起过节，太可惜了。正这样想着，外祖母已经点亮了灯，端过来说：“来，咱们 重新过节。” 妈妈一下醒悟过来，赶紧和外祖母一起忙活：大圆木桌被再次抬到了院子里，一个 个碟子钵子全端出来了。特别是酒瓶和杯子，它们一样不少地摆在了桌上。月亮已经歪 到了西边，不过天色还是很亮，空中没有二丝云彩。一只小鸟在不远处叫了一声，有什 么动物在附近的树上跳跃着。啊，我们要接着过节。 这时候我们都想到了一件事，这也很重要：让小花猫认识一下爸爸。是啊，我们家 里又添了一口，它还没有见过一家之主呢。外祖母大声呼唤，妈妈也起身去找。到处都 没有。我伏下身子到处看，觉得它一定是钻到了一个，角落里，因为害怕生人。我说： “小花猫别怕，是爸爸回来了，我以前跟你讲过啊，是他回家了!” 爸爸很快弄明白了是怎么一回事，就笑着等待。爸爸坐在月光里，桌子旁，身体挺 得笔直。我觉得他对这次见面非常看重。可是", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第23题；官方原卷未附答案"}, {"q": "第一段中，面对家人的惊喜，为什么爸爸的语气却“十分平静”? (2 分)", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第24题；官方原卷未附答案"}, {"q": "分析第三段中画线句子的作用。(3分)", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第25题；官方原卷未附答案"}, {"q": "作者为什么要写爸爸谈的“另外些事情”?(3 分)", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第26题；官方原卷未附答案"}, {"q": "小说构思巧妙，结构紧凑。结合全文作简要分析。(3 分)", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第27题；官方原卷未附答案"}, {"q": "校园广播站“美文共赏”栏目打算在中秋节期间，把这篇小说推荐给全校同学。请结合 小说的内容和情感，代主持人完成下面的段话，不超过80 字。(4 分) “露从今夜白，月是故乡明。”同学们好，中秋佳节即将到来，你是否已经开始思念 故乡和亲人?有这样一篇文章，讲的是一位父亲__________________。这就是作家张炜 的小说《追月人》，下面请欣赏。 六、(本大题45 分)", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第28题；官方原卷未附答案"}, {"q": "阅读下面的材料，根据要求完成作文。 韩愈在《师说》中强调：“无贵无贱，无长无少，道之所存，师之所存也。” 其实，不只是课堂上的老师教给我们为人之道、处世之理，让我们获取知识，修养 品格；亲朋好友、书籍网络、音乐舞蹈、山水田园……皆可成为我们的老师。 请以“亦为吾师”为题目，写一篇作文。 要求：①补全题目；②除诗歌外，文体不限；③不少于700 字；④文中不得透露本 人相关信息。", "typ": "write", "ans": "", "note": "2021年山东春季高考语文真题第29题；官方原卷未附答案"}]}]};
